  1	import { useState } from "react";
  2	import { Image } from "expo-image";
  3	import { Upload, FolderDown, ImageOff } from "lucide-react-native";
  4	import { toast, toastError } from "@/components/ui/toast";
  5	import { ScreenWrapper } from "@/components/common/screen-wrapper";
  6	import { BackHeader } from "@/components/common/back-header";
  7	import { SettingsGroup } from "@/components/settings/settings-group";
  8	import { SettingsRow } from "@/components/settings/settings-row";
  9	import { SettingsToggleRow } from "@/components/settings/settings-toggle-row";
 10	import { useConfigStore } from "@/store/config-store";
 11	import type { ExportStage, ImportStage } from "@/store/config-store";
 12	import { ProgressModal } from "@/components/common/progress-modal";
 13	import { ConfirmModal } from "@/components/common/confirm-modal";
 14	import { PassphrasePrompt } from "@/components/common/passphrase-prompt";
 15	import type { PassphraseResult } from "@/components/common/passphrase-prompt";
 16	import { useModalFlow } from "@/hooks/use-modal-flow";
 17	import { reevaluateHomeNetworkAfterImport } from "@/lib/network";
 18	import {
 19	  EXPORT_STAGE_COPY,
 20	  IMPORT_STAGE_COPY,
 21	  usePassphrasePrompt,
 22	} from "@/hooks/use-passphrase-prompt";
 23	import type { PassphraseRequest } from "@/hooks/use-passphrase-prompt";
 24	
 25	export default function BackupSettingsScreen() {
 26	  const [exportStage, setExportStage] = useState<ExportStage | null>(null);
 27	  const [importStage, setImportStage] = useState<ImportStage | null>(null);
 28	
 29	  const exportConfig = useConfigStore((s) => s.exportConfig);
 30	  const importConfig = useConfigStore((s) => s.importConfig);
 31	  const demoMode = useConfigStore((s) => s.demoMode);
 32	  const enableDemoMode = useConfigStore((s) => s.enableDemoMode);
 33	  const disableDemoMode = useConfigStore((s) => s.disableDemoMode);
 34	
 35	  // Modal sequencing (confirm → document picker, passphrase prompt →
 36	  // ProgressModal/share sheet) goes through the flow — see
 37	  // hooks/use-modal-flow.ts. The passphrase promise resolves only once the
 38	  // prompt is fully dismissed, so whatever follows never presents mid-dismiss.
 39	  const flow = useModalFlow<{
 40	    confirmClearCache: void;
 41	    confirmImport: void;
 42	    passphrase: PassphraseRequest;
 43	  }>();
 44	
 45	  const { hasRemembered, requestPassphrase, syncRememberedState, useRemembered } =
 46	    usePassphrasePrompt((request) => flow.open("passphrase", request));
 47	
 48	  const handleExport = async () => {
 49	    const result = await requestPassphrase("export");
 50	    if (!result) return;
 51	    try {
 52	      await exportConfig(result.passphrase, setExportStage, async () => {
 53	        // Reflect the "Remember on this device" choice while the app is still
 54	        // foregrounded, before the share app-switch (see exportConfig / #180).
 55	        // Best-effort: the export file is already written, so failing to
 56	        // remember the passphrase must not abort the share or read as an export
 57	        // failure. Mirror loadRememberedPassphrase, which degrades silently — a
 58	        // user who cancels the biometric prompt knows it, and a genuine failure
 59	        // just means they re-enter the passphrase next time.
 60	        try {
 61	          await syncRememberedState(result);
 62	        } catch (err) {
 63	          console.warn("Failed to persist remembered passphrase", err);
 64	        }
 65	      });
 66	    } catch (e) {
 67	      toastError("Failed to export config", e);
 68	    } finally {
 69	      setExportStage(null);
 70	    }
 71	  };
 72	
 73	  const performClearImageCache = async () => {
 74	    flow.close();
 75	    try {
 76	      await Promise.all([Image.clearMemoryCache(), Image.clearDiskCache()]);
 77	      toast("Image cache cleared", "success");
 78	    } catch (err) {
 79	      toastError("Failed to clear image cache", err);
 80	    }
 81	  };
 82	
 83	  // Runs via flow.whenClear from the import confirm, so the document picker
 84	  // never presents while the ConfirmModal is still animating away.
 85	  const performImport = async () => {
 86	    // Captured from the requestPassphrase callback below — only set
 87	    // if the picked file was encrypted and the user supplied a
 88	    // passphrase. Plain-JSON legacy backups leave this null.
 89	    let capturedResult: PassphraseResult | null = null;
 90	    try {
 91	      const success = await importConfig(async () => {
 92	        capturedResult = await requestPassphrase("import");
 93	        return capturedResult?.passphrase ?? null;
 94	      }, setImportStage);
 95	      if (success) {
 96	        if (capturedResult) await syncRememberedState(capturedResult);
 97	        toast("Configuration imported successfully", "success");
 98	        // Import resets the away flag to its safe default, so local-only
 99	        // services start "remote-only" until home is re-confirmed. Prompt for
100	        // Location + re-evaluate now so they come back online on the home WiFi
101	        // without the user hunting for a permission (#168). The import already
102	        // succeeded, so this runs detached — but if we're STILL away once it
103	        // settles (permission denied, no home network configured, or genuinely
104	        // away), tell the user why their services are on remote URLs and where
105	        // to fix it, instead of leaving every service silently stuck on remote.
106	        void reevaluateHomeNetworkAfterImport().then(() => {
107	          const st = useConfigStore.getState();
108	          if (st.autoSwitchNetwork && st.networkAwayFromHome) {
109	            toast(
110	              "Services are using remote URLs until your home WiFi is confirmed. Open Settings → Network → Home Networks to finish setup.",
111	              "info",
112	            );
113	          }
114	        });
115	      }
116	    } catch (e) {
117	      toastError("Invalid config file", e);
118	    } finally {
119	      setImportStage(null);
120	    }
121	  };
122	
123	  return (
124	    <ScreenWrapper>
125	      <BackHeader title="Backup & Storage" />
126	
127	      <SettingsGroup
128	        title="Backup & Storage"
129	        footer="Backups are encrypted with a passphrase you choose. Keep it safe — without it the backup cannot be restored."
130	      >
131	        <SettingsRow
132	          icon={Upload}
133	          label="Export settings"
134	          subtitle="Save an encrypted backup file"
135	          onPress={handleExport}
136	          disabled={exportStage !== null}
137	        />
138	        <SettingsRow
139	          icon={FolderDown}
140	          label="Import settings"
141	          subtitle="Restore from a backup file"
142	          onPress={() => flow.open("confirmImport")}
143	          disabled={importStage !== null}
144	        />
145	        <SettingsRow
146	          icon={ImageOff}
147	          label="Clear image cache"
148	          subtitle="Free up disk space used by cached posters and backdrops"
149	          onPress={() => flow.open("confirmClearCache")}
150	        />
151	      </SettingsGroup>
152	
153	      <SettingsGroup title="Advanced">
154	        <SettingsToggleRow
155	          label="Demo Mode"
156	          description="Show sample data — no server required"
157	          value={demoMode}
158	          onValueChange={(v) => {
159	            if (v) {
160	              enableDemoMode();
161	            } else {
162	              void disableDemoMode();
163	            }
164	          }}
165	        />
166	      </SettingsGroup>
167	
168	      <ProgressModal
169	        visible={exportStage !== null}
170	        title={exportStage ? EXPORT_STAGE_COPY[exportStage].title : ""}
171	        subtitle={exportStage ? EXPORT_STAGE_COPY[exportStage].subtitle : undefined}
172	      />
173	
174	      <ProgressModal
175	        visible={importStage !== null}
176	        title={importStage ? IMPORT_STAGE_COPY[importStage].title : ""}
177	        subtitle={importStage ? IMPORT_STAGE_COPY[importStage].subtitle : undefined}
178	      />
179	
180	      <ConfirmModal
181	        {...flow.bind("confirmClearCache")}
182	        title="Clear image cache"
183	        message="Posters and backdrops will be re-downloaded the next time you view them."
184	        icon={ImageOff}
185	        tone="danger"
186	        confirmLabel="Clear"
187	        onConfirm={() => void performClearImageCache()}
188	      />
189	
190	      <ConfirmModal
191	        {...flow.bind("confirmImport")}
192	        title="Import settings"
193	        message="This will overwrite all current settings with the imported configuration. Continue?"
194	        icon={FolderDown}
195	        tone="danger"
196	        confirmLabel="Import"
197	        onConfirm={() => {
198	          flow.close();
199	          flow.whenClear(() => void performImport());
200	        }}
201	      />
202	
203	      <PassphrasePrompt
204	        visible={flow.isOpen("passphrase")}
205	        mode={flow.payload("passphrase")?.mode ?? "import"}
206	        hasRemembered={hasRemembered}
207	        onUseRemembered={useRemembered}
208	        onSubmit={(result) => {
209	          const request = flow.payload("passphrase");
210	          flow.close();
211	          flow.whenClear(() => request?.resolve(result));
212	        }}
213	        onCancel={() => {
214	          const request = flow.payload("passphrase");
215	          flow.close();
216	          flow.whenClear(() => request?.resolve(null));
217	        }}
218	        onClosed={flow.onClosed}
219	      />
220	    </ScreenWrapper>
221	  );
222	}

