     3	import { pbkdf2Async } from "@noble/hashes/pbkdf2.js";
     4	import { sha256 } from "@noble/hashes/sha2.js";
     5	
     6	/**
     7	 * Random bytes source. The app binds expo-crypto (lib/config-crypto.ts); the
     8	 * backend's web editor binds `crypto.getRandomValues`. Injected rather than
     9	 * imported so this module stays free of Expo and works in a browser bundle,
    10	 * including plain-http LAN origins where WebCrypto's `subtle` is unavailable
    11	 * but `getRandomValues` is not.
    12	 */
    13	export type Rng = (length: number) => Uint8Array;
    14	
    15	const FORMAT = "dashboarr-encrypted-v1" as const;
    16	// PBKDF2-SHA256 runs in pure JS on Hermes, which is much slower than native
    17	// crypto. 100k is a mobile-practical balance — still adds ~17 bits of work
    18	// against a brute-force attack on top of the 8+ char passphrase requirement.
    19	export const PBKDF2_ITERATIONS = 100_000;
    20	const KEY_LENGTH = 32; // AES-256
    21	const SALT_LENGTH = 16;
    22	const NONCE_LENGTH = 12; // GCM standard
    23	const MIN_PASSPHRASE_LENGTH = 8;
    24	// Refuse to even attempt KDF on suspicious envelopes — protects against
    25	// ~infinite iteration counts in a crafted file that would freeze the app.
    26	const MAX_ITERATIONS = 10_000_000;
    27	const MIN_ITERATIONS = 10_000;
    28	
    29	export interface EncryptedEnvelope {
    30	  format: typeof FORMAT;
    31	  kdf: { name: "pbkdf2-sha256"; iterations: number; salt: string };
    32	  cipher: { name: "aes-256-gcm"; nonce: string; ciphertext: string };
    33	}
    34	
    35	export function isEncryptedEnvelope(v: unknown): v is EncryptedEnvelope {
