    43	function assertIsEnvelope(v: unknown): asserts v is EncryptedEnvelope {
    44	  if (!isEncryptedEnvelope(v)) throw new Error("Not an encrypted config file");
    45	  const env = v as EncryptedEnvelope;
    46	  if (env.kdf?.name !== "pbkdf2-sha256") throw new Error("Unsupported KDF");
    47	  if (env.cipher?.name !== "aes-256-gcm") throw new Error("Unsupported cipher");
    48	  if (typeof env.kdf.salt !== "string") throw new Error("Missing KDF salt");
    49	  if (typeof env.cipher.nonce !== "string") throw new Error("Missing cipher nonce");
    50	  if (typeof env.cipher.ciphertext !== "string") throw new Error("Missing ciphertext");
    51	  if (
    52	    typeof env.kdf.iterations !== "number" ||
    53	    !Number.isInteger(env.kdf.iterations) ||
    54	    env.kdf.iterations < MIN_ITERATIONS ||
    55	    env.kdf.iterations > MAX_ITERATIONS
