    84	export async function deriveKeyHex(
    85	  passphrase: string,
    86	  saltHex: string,
    87	  iterations: number = PBKDF2_ITERATIONS,
    88	): Promise<string> {
    89	  if (typeof passphrase !== "string" || passphrase.length < MIN_PASSPHRASE_LENGTH) {
    90	    throw new Error(`Passphrase must be at least ${MIN_PASSPHRASE_LENGTH} characters`);
