   119	    kdf: { name: "pbkdf2-sha256", iterations: key.iterations, salt: key.saltHex },
   120	    cipher: { name: "aes-256-gcm", nonce: bytesToHex(nonce), ciphertext: bytesToHex(ciphertext) },
   121	  };
   122	}
   123	
   124	export async function encryptJsonString(
   125	  plainJson: string,
   126	  passphrase: string,
   127	  rng: Rng,
   128	): Promise<EncryptedEnvelope> {
   129	  if (typeof passphrase !== "string" || passphrase.length < MIN_PASSPHRASE_LENGTH) {
