  3	import { bytesToHex, utf8ToBytes } from "@noble/ciphers/utils.js";
  4	import { NATIVE_VERSION } from "@/lib/app-version";
  5	import { encryptJsonStringWithKey } from "@/lib/config-crypto";
  6	import { STORAGE_KEYS } from "@/lib/constants";
  7	import { putConfigBackup } from "@/services/backend-api";
  8	import { useBackendStore } from "@/store/backend-store";
  9	import { buildExportPayload, useConfigStore } from "@/store/config-store";
 10	import type { ExportPayload } from "@/store/config-store";
 11	import { deleteKey, getString, setString } from "@/store/storage";
 12	
 13	/**
 14	 * Continuous encrypted config backup to the paired backend (Refs #385).
 15	 *
 16	 * Uploads the same envelope the file export produces, encrypted with the key
 17	 * derived once when the user turned the feature on (store/backend-store.ts),
 18	 * so an upload costs one AES pass, not a PBKDF2 run. The backend keeps one
 19	 * slot per device and never sees the passphrase.
 20	 *
 21	 * Skips: demo mode (the store holds fake instances that would overwrite the
 22	 * real backup), stores not hydrated, feature off, and unchanged payloads
 23	 * (hash of everything but `exportedAt`).
 24	 */
 25	
 26	const DEBOUNCE_MS = 15_000;
 27	
 28	export interface BackupPlaintext {
 29	  json: string;
 30	  hash: string;
 31	  configVersion: number;
 32	  exportedAt: number;
 33	}
 34	
 35	/**
 36	 * The payload to encrypt. `backend` is stripped on purpose: a phone restoring
 37	 * this must keep its own pairing, and the uploader's bearer must never travel
 38	 * to another device even inside ciphertext.
 39	 */
 40	export function buildBackupPlaintext(): BackupPlaintext {
 41	  const payload: ExportPayload = buildExportPayload();
 42	  delete payload.backend;
 43	  const { exportedAt, ...stable } = payload;
 44	  const hash = bytesToHex(sha256(utf8ToBytes(JSON.stringify(stable))));
 45	  return {
 46	    json: JSON.stringify(payload),
 47	    hash,
 48	    configVersion: payload.version,
 49	    exportedAt: Date.parse(exportedAt) || Date.now(),
 50	  };
 51	}
 52	
 53	export type UploadOutcome = "uploaded" | "skipped";
 54	
 55	function describeUploadError(err: unknown): string {
 56	  const status = (err as { status?: number } | null)?.status;
 57	  if (status === 413) return "Backup is larger than the backend accepts (4 MB)";
 58	  if (status === 404) return "This backend does not support config backups yet (update it to 1.6 or newer)";
 59	  return err instanceof Error ? err.message : String(err);
 60	}
 61	
 62	let inflight: Promise<UploadOutcome> | null = null;
 63	let rerunForced = false;
 64	let rerunRequested = false;
 65	
 66	async function runUpload(force: boolean): Promise<UploadOutcome> {
 67	  const backend = useBackendStore.getState();
 68	  const config = useConfigStore.getState();
 69	  if (!backend.hydrated || !config.hydrated) return "skipped";
 70	  if (
 71	    !backend.backupEnabled ||
 72	    !backend.backupSaltHex ||
 73	    !backend.backupKeyHex ||
 74	    !backend.backupKeyIterations
 75	  ) {
 76	    return "skipped";
 77	  }
 78	  if (!backend.sharedSecret || !backend.url) return "skipped";
 79	  if (config.demoMode) return "skipped";
 80	
 81	  const plain = buildBackupPlaintext();
 82	  if (!force && getString(STORAGE_KEYS.backendBackupLastHash) === plain.hash) return "skipped";
 83	
 84	  backend.setBackupStatus({ backupInFlight: true });
 85	  try {
 86	    const envelope = encryptJsonStringWithKey(plain.json, {
 87	      saltHex: backend.backupSaltHex,
 88	      keyHex: backend.backupKeyHex,
 89	      iterations: backend.backupKeyIterations,
 90	    });
 91	    const result = await putConfigBackup({
 92	      envelope,
 93	      configVersion: plain.configVersion,
 94	      exportedAt: plain.exportedAt,
 95	      appVersion: NATIVE_VERSION,
 96	    });
 97	    setString(STORAGE_KEYS.backendBackupLastHash, plain.hash);
 98	    setString(STORAGE_KEYS.backendBackupLastAt, String(result.updatedAt));
 99	    useBackendStore.getState().setBackupStatus({
100	      lastBackupAt: result.updatedAt,
101	      lastBackupError: null,
102	      backupInFlight: false,
103	    });
104	    return "uploaded";
105	  } catch (err) {
106	    // A failed upload must not leave a matching hash behind, or the next
107	    // change-free tick would skip the retry forever.
108	    deleteKey(STORAGE_KEYS.backendBackupLastHash);
109	    useBackendStore.getState().setBackupStatus({
110	      lastBackupError: describeUploadError(err),
111	      backupInFlight: false,
112	    });
113	    throw new Error(describeUploadError(err));
114	  }
115	}
116	
117	/**
118	 * Encrypt and upload the current config. Overlapping calls coalesce: while
119	 * one upload is in flight, later calls wait for it and then run once more
120	 * (forced if any of them was), so the last state always lands.
121	 */
122	export function uploadConfigBackup(opts: { force?: boolean } = {}): Promise<UploadOutcome> {
123	  const force = opts.force ?? false;
124	  if (inflight) {
125	    rerunRequested = true;
126	    rerunForced = rerunForced || force;
127	    return inflight;
128	  }
129	  inflight = (async () => {
130	    try {
131	      let outcome = await runUpload(force);
132	      while (rerunRequested) {
133	        const again = rerunForced;
134	        rerunRequested = false;
135	        rerunForced = false;
136	        outcome = await runUpload(again);
137	      }
138	      return outcome;
139	    } finally {
140	      inflight = null;
141	      rerunRequested = false;
142	      rerunForced = false;
143	    }
144	  })();
145	  return inflight;
146	}
147	
148	let timer: ReturnType<typeof setTimeout> | null = null;
149	let pendingWhileBackground = false;
150	
151	/**
152	 * Debounced upload for the ConfigSyncBridge. Fires only while the app is
153	 * active; a change made in the background is flushed on the next resume via
154	 * `flushPendingConfigBackup`.
155	 */
156	export function scheduleConfigBackup(): void {
157	  if (timer) clearTimeout(timer);
158	  timer = setTimeout(() => {
159	    timer = null;
160	    if (AppState.currentState !== "active") {
161	      pendingWhileBackground = true;
162	      return;
163	    }
164	    void uploadConfigBackup().catch((err) => {
165	      console.warn("[backend-backup] upload failed", err);
166	    });
167	  }, DEBOUNCE_MS);
168	}
169	
170	export function flushPendingConfigBackup(): void {
171	  if (!pendingWhileBackground) return;
172	  pendingWhileBackground = false;
173	  void uploadConfigBackup().catch((err) => {
174	    console.warn("[backend-backup] upload failed", err);
175	  });
176	}
177	
178	export function cancelScheduledConfigBackup(): void {
179	  if (timer) clearTimeout(timer);
180	  timer = null;
181	  pendingWhileBackground = false;
182	}
183	
184	/** Restore the persisted "last backup" timestamp into the store after hydration. */
185	export function loadBackupStatus(): void {
186	  const raw = getString(STORAGE_KEYS.backendBackupLastAt);
187	  const at = raw ? Number(raw) : NaN;
188	  if (Number.isFinite(at)) useBackendStore.getState().setBackupStatus({ lastBackupAt: at });
189	}

