 45	  // otherwise it falls back to torrentBadgeVariant(status). qBittorrent sets
 46	  // this to preserve its exact per-state colors (e.g. stalledUP stays green);
 47	  // rtorrent omits it and uses the normalized default.
 48	  badgeVariant?: DownloadBadgeVariant;
 49	  // Category (qBittorrent) / custom1 label (rtorrent). Single string.
 50	  label: string;
 51	  tags: string; // qBittorrent comma tags; rtorrent ""
 52	  addedOn: number; // unix seconds
 53	  completedOn?: number; // unix seconds; undefined when the client doesn't expose it
 54	  savePath: string;
