 66	  dlSpeed: number; // bytes/s now
 67	  upSpeed: number; // bytes/s now
 68	  dlTotalLifetime: number; // bytes
 69	  upTotalLifetime: number; // bytes
 70	  dlLimit: number; // bytes/s, 0 = unlimited
 71	  upLimit: number; // bytes/s, 0 = unlimited
 72	}
