114	
115	// Uniform list result. THE abstraction that hides server-vs-client pagination:
116	// qBittorrent wraps useInfiniteQuery (real pages); rtorrent wraps useQuery
117	// (fetch-all, hasNextPage:false, fetchNextPage no-op). The view reads
118	// `torrents` and renders without knowing which client it's on.
119	export interface TorrentListResult {
120	  torrents: UnifiedTorrent[];
121	  isLoading: boolean;
122	  isRefetching: boolean;
123	  error: Error | null;
124	  hasNextPage: boolean;
125	  isFetchingNextPage: boolean;
126	  isFetchNextPageError: boolean;
127	  fetchNextPage: () => void;
128	  refetch: () => Promise<unknown>;
129	}
130	
131	// What the add card (and the indexer grab flows) hand to useAddTorrent. A
132	// magnet / http(s) .torrent link goes as `uri`; a local .torrent picked from
133	// the Files app or opened from the OS goes as `file`. The `never` halves keep
134	// the two exclusive at the type level while `{ uri, label }` call sites stay
135	// untouched.
136	export type AddTorrentInput = (
137	  | { uri: string; file?: never }
138	  | { file: TorrentFileSource; uri?: never }
139	) & {
140	  label?: string;
141	  savePath?: string;
142	};
143	
144	// Every adapter's useAddTorrent mutation carries this key so the Downloads
145	// screen can ask the mutation cache whether an add is in flight
146	// (useIsMutating) and freeze client switching until it settles: a switch
147	// remounts the shared view, and a remounted view would re-stage the same
148	// file with an idle mutation while the old upload is still streaming it.
149	export const TORRENT_ADD_MUTATION_KEY = ["torrentAdd"] as const;
150	
151	// Shared adapter: each torrent client implements one of these and the shared
152	// downloads view branches on no client-specific knowledge beyond what the
153	// adapter + capability flags expose.
154	export interface TorrentAdapter {
155	  serviceId: ServiceId;
156	  displayName: string;
157	  capabilities: TorrentCapabilities;
158	
159	  // Detail-screen deep-link for a single torrent (only used when
160	  // capabilities.perTorrentFiles is true).
161	  //
162	  // `instanceId` is the server the row came from. It matters on the dashboard
163	  // Downloads widget, which aggregates every configured instance of a kind
164	  // without changing the active one: a route carrying only the hash lands the
165	  // detail screen on whatever instance happens to be active, so a torrent from
166	  // a second server reads as "not found" — or, when the same hash exists on
167	  // both, pause/delete hits the wrong server. Adapters that pin the instance
168	  // encode it in the route; the rest ignore the argument and keep following
169	  // the active instance.
170	  detailRoute: (hash: string, instanceId?: string | null) => string;
171	
172	  // The list hook — abstracts server-vs-client pagination (see TorrentListResult).
173	  useTorrents: (opts: TorrentListFilter, instanceId?: string) => TorrentListResult;
174	
175	  // Category names for the category filter. Always called by the shared view
176	  // (so it must be a stable hook), but only surfaced when
177	  // capabilities.categories is true. Clients without categories return []. The
178	  // returned names map 1:1 onto the values the view passes back via
179	  // TorrentListFilter.category.
180	  useCategories: (instanceId?: string) => string[];
181	
182	  // Global transfer stats for the per-tab speed header.
183	  useGlobalStats: (instanceId?: string) => UseQueryResult<TorrentGlobalStats>;
184	
185	  // Per-instance query options for `useQueries` fan-outs in dashboard widgets
186	  // that aggregate across every enabled instance. `select` already maps to the
187	  // normalized shape.
188	  globalStatsQueryOptions: (
189	    instanceId: string,
190	  ) => UseQueryOptions<unknown, Error, TorrentGlobalStats>;
191	  torrentsQueryOptions: (
192	    instanceId: string,
193	  ) => UseQueryOptions<unknown, Error, UnifiedTorrent[]>;
194	
195	  usePauseTorrent: (instanceId?: string) => UseMutationResult<unknown, Error, string[]>;
196	  useResumeTorrent: (instanceId?: string) => UseMutationResult<unknown, Error, string[]>;
197	  useDeleteTorrent: (
198	    instanceId?: string,
199	  ) => UseMutationResult<unknown, Error, { hashes: string[]; deleteFiles?: boolean }>;
200	  // Add by magnet/URL (`uri`) or by uploading a local .torrent (`file`, see
201	  // lib/torrent-file.ts). Exactly one of the two is set; `label` and
202	  // `savePath` apply to both.
203	  useAddTorrent: (
204	    instanceId?: string,
205	  ) => UseMutationResult<unknown, Error, AddTorrentInput>;
206	
207	  // Assign/clear a torrent's category (qBittorrent only — gated by
208	  // capabilities.categories). category "" clears it. Always called by the
209	  // shared view (like useCategories), so clients without categories return a
210	  // stub mutation that's never invoked.
211	  useSetCategory: (
212	    instanceId?: string,
213	  ) => UseMutationResult<unknown, Error, { hashes: string[]; category: string }>;
214	
215	  // Optional self-contained speed-limits header control (button + sheet + its
216	  // own hooks). Rendered in the speed-summary row when present. Owning all the
217	  // client-specific speed-limit hooks here keeps the shared view free of any
218	  // optional-hook (rules-of-hooks) hazard.
219	  SpeedLimitsControl?: ComponentType;
220	}
221	
222	// Maps a normalized status to the shared Badge component's variant vocabulary —
223	// mirrors usenetBadgeVariant.
224	export function torrentBadgeVariant(status: TorrentStatus): DownloadBadgeVariant {
225	  switch (status) {
226	    case "downloading":
227	      return "downloading";
228	    case "seeding":
229	      return "seeding";
230	    case "paused":
231	      return "paused";
232	    case "errored":
233	      return "error";
234	    case "stalled":
235	    case "checking":
236	    case "queued":
237	    case "other":
238	      return "default";
239	  }
240	}

