    43	
    44	// "all" omits the qBittorrent `filter` param rather than sending `filter=all`
    45	// (functionally identical, a few bytes cheaper). The remaining values map 1:1.
    46	function tabFilterToQB(filter: TorrentFilterType): QBTorrentFilter | undefined {
    47	  return filter === "all" ? undefined : filter;
    48	}
    49	
    50	// Sort key from the downloads sort store → qBittorrent's server-side `sort`
    51	// field name + `reverse`.
    52	function sortKeyToQB(key: DownloadsSortKey): { sort: keyof QBTorrent; reverse: boolean } {
    53	  switch (key) {
    54	    case "progress-desc":
    55	      return { sort: "progress", reverse: true };
    56	    case "progress-asc":
    57	      return { sort: "progress", reverse: false };
    58	    case "name-asc":
    59	      return { sort: "name", reverse: false };
    60	    case "size-desc":
    61	      return { sort: "size", reverse: true };
    62	    case "added-desc":
    63	      return { sort: "added_on", reverse: true };
    64	  }
    65	}
    66	
    67	function qbStatusToUnified(state: TorrentState): TorrentStatus {
    68	  if (state === "error" || state === "missingFiles") return "errored";
    69	  if (
