35	  serviceId: ServiceId,
36	  instanceId?: string,
37	): { instanceId: string | null; enabled: boolean } {
38	  // Only the workspace-resolved active instance (attachment + enabled aware).
39	  // No raw serviceInstances[serviceId][0] tail: when nothing is enabled+attached
40	  // in the active workspace this is null, which gates dependent queries off via
41	  // `enabled` below — instead of silently following another workspace's
42	  // instance and rendering its data (#3).
