185	export function useDeleteMovie(instanceId?: string) {
186	  const queryClient = useQueryClient();
187	  const { instanceId: id } = useInstanceTarget("radarr", instanceId);
188	  // Overseerr cleanup runs against the active Overseerr instance; cross-stack
189	  // deletion is a UX nicety, not a contract.
190	  const overseerrEnabled = useConfigStore((s) => s.services.overseerr.enabled);
191	  // DELETE /media needs MANAGE_REQUESTS; a Seerr signed in as a plain member
192	  // (#332) would only 403, so skip the round trip silently for that account.
193	  // Only a CONFIRMED denial skips: before /auth/me has answered the hook
194	  // reports every capability false, so the mutation resolves it on demand.
195	  const seerrCaps = useSeerrCapabilities();
196	  return useMutation({
197	    mutationFn: async ({
198	      id: movieId,
199	      deleteFiles = false,
200	      addExclusion = false,
201	      tmdbId,
202	    }: {
203	      id: number;
204	      deleteFiles?: boolean;
205	      addExclusion?: boolean;
206	      tmdbId?: number;
207	    }) => {
208	      await deleteMovie(movieId, { deleteFiles, addExclusion }, id ?? undefined);
209	      // Clear Overseerr media entry so the movie can be re-requested
210	      if (tmdbId && overseerrEnabled) {
211	        try {
212	          const canManage = seerrCaps.loaded
213	            ? seerrCaps.canManageRequests
214	            : deriveSeerrCapabilities(await getSeerrMe()).canManageRequests;
215	          if (!canManage) return;
216	          const details = await getMovieDetails(tmdbId);
217	          if (details.mediaInfo?.id) {
218	            await deleteMedia(details.mediaInfo.id);
219	          }
220	        } catch {
221	          // Non-critical — don't block Radarr delete if Overseerr cleanup fails
222	        }
223	      }
224	    },
225	    onSuccess: () => {
226	      queryClient.invalidateQueries({ queryKey: ["radarr", id, "movies"] });
227	      queryClient.invalidateQueries({ queryKey: ["overseerr"] });
228	    },
229	  });
230	}
