589	    if (serviceId === "nzbget") headers.set("Content-Type", "application/json");
590	  } else if (serviceId === "plex") {
591	    if (secrets.apiKey) {
592	      headers.set("X-Plex-Token", secrets.apiKey);
593	      headers.set("Accept", "application/json");
594	    }
595	  } else if (serviceId === "jellyfin" || serviceId === "emby") {
596	    // Jellyfin gates the Emby-era X-Emby-Token header behind the server's
597	    // EnableLegacyAuthorization flag; applyMediaServerAuth sends the
598	    // Authorization: MediaBrowser shape that survives it, or hands back the
599	    // ApiKey query param when a proxy already owns that header (#399).
