  1	import type {
  2	  ArrQualityModel,
  3	  RadarrManualImportItem,
  4	  SonarrManualImportItem,
  5	} from "@/lib/types";
  6	
  7	/**
  8	 * Manual import — the app-side equivalent of Radarr's and Sonarr's own
  9	 * Interactive/Manual Import screen (#306).
 10	 *
 11	 * `GET /manualimport?downloadId=` returns the files *arr found for a completed
 12	 * download plus whatever it managed to match them to. One-tap force import
 13	 * (#325) only works when *arr matched everything itself; when the release is
 14	 * named in a way it can't parse, `series`/`movie`/`episodes` come back empty
 15	 * and the mapping has to be supplied by hand. That is what this module models:
 16	 * a normalized candidate shape both services share, and the two `files[]`
 17	 * payloads their `ManualImport` command takes.
 18	 *
 19	 * `GET /manualimport?folder=` is the same scan over any folder on the *arr host
 20	 * (#470); its files carry no downloadId, so the payloads below simply omit it.
 21	 *
 22	 * Kept pure (no React, no network) so the payload shapes — the part that fails
 23	 * silently against a real server — are unit-testable.
 24	 */
 25	
 26	export type ManualImportService = "radarr" | "sonarr";
 27	
 28	/**
 29	 * Where the files come from: a stuck download (#306), or any folder on the
 30	 * *arr host (#470). The two differ in the /manualimport lookup and, more
 31	 * importantly, in what the command does with the source files.
 32	 */
 33	export type ManualImportSource =
 34	  | { kind: "download"; downloadId: string }
 35	  | { kind: "folder"; folder: string };
 36	
 37	/** The ManualImport command's `importMode` (ImportMode: Auto, Move, Copy). */
 38	export type ArrImportMode = "auto" | "move" | "copy";
 39	
 40	/** The two modes a folder import may use. "copy" hardlinks when *arr is set to. */
 41	export type FolderImportMode = Exclude<ArrImportMode, "auto">;
 42	
 43	/**
 44	 * The importMode to send for a source.
 45	 *
 46	 * A download keeps "auto", which lets *arr follow the download client (copy
 47	 * while a torrent still seeds, move otherwise). A folder must never send it:
 48	 * "auto" only copies when there is a download-client item that can't move, and
 49	 * a folder import has none, so on the server it means MOVE
 50	 * (ImportApprovedMovie / ImportApprovedEpisodes). The user picks instead, the
 51	 * same choice Radarr's and Sonarr's own folder import forces.
 52	 */
 53	export function resolveImportMode(
 54	  source: ManualImportSource,
 55	  chosen: FolderImportMode | undefined,
 56	): ArrImportMode {
 57	  if (source.kind === "download") return "auto";
 58	  if (!chosen) throw new Error("Choose whether to move or copy the files.");
 59	  return chosen;
 60	}
 61	
 62	/** A candidate file from `GET /manualimport`, normalized across both services. */
 63	export interface ManualImportCandidate {
 64	  /** Candidate id; unique within one /manualimport response, used as the key. */
 65	  id: number;
 66	  /** Absolute path on the *arr host — the field the command imports by. */
 67	  path: string;
 68	  folderName?: string;
 69	  /** File name for display: the relative path, else the basename of `path`. */
 70	  name: string;
 71	  size: number;
 72	  /** What *arr matched on its own: a Sonarr series id / a Radarr movie id. */
 73	  mediaId?: number;
 74	  mediaTitle?: string;
 75	  /** Sonarr only — its guess at the season, and the episodes it resolved. */
 76	  seasonNumber?: number;
 77	  episodeIds: number[];
 78	  episodeFileId?: number;
 79	  releaseType?: string;
 80	  /** Parsed off the file name; absent when *arr could not parse one. */
 81	  quality?: ArrQualityModel;
 82	  languages: { id: number; name: string }[];
 83	  releaseGroup?: string;
 84	  indexerFlags: number;
 85	  /** Why *arr refused to import the file, deduped. */
 86	  rejections: string[];
 87	}
 88	
 89	/** One file plus the destination it will be imported to. */
 90	export interface ManualImportRow {
 91	  candidate: ManualImportCandidate;
 92	  /** Sonarr: the series id. Radarr: the movie id. */
 93	  mediaId: number;
 94	  quality: ArrQualityModel;
 95	  /** Sonarr only; ignored by the Radarr payload. */
 96	  episodeIds: number[];
 97	}
 98	
 99	/** `files[]` entry of Sonarr's ManualImport command. */
100	export interface SonarrManualImportFile {
101	  path: string;
102	  folderName?: string;
103	  seriesId: number;
104	  episodeIds: number[];
105	  quality: ArrQualityModel;
106	  languages: { id: number; name: string }[];
107	  releaseGroup?: string;
108	  indexerFlags: number;
109	  releaseType?: string;
110	  episodeFileId?: number;
111	  downloadId?: string;
112	}
113	
114	/** `files[]` entry of Radarr's ManualImport command. */
115	export interface RadarrManualImportFile {
116	  path: string;
117	  folderName?: string;
118	  movieId: number;
119	  quality: ArrQualityModel;
120	  languages: { id: number; name: string }[];
121	  releaseGroup?: string;
122	  indexerFlags: number;
123	  downloadId?: string;
124	}
125	
126	// `relativePath` is what both web UIs show; `path` is absolute and `name` is
127	// only set on some records, so both are fallbacks rather than the first choice.
128	function fileName(item: {
129	  relativePath?: string;
130	  path?: string;
131	  name?: string;
132	}): string {
133	  if (item.relativePath) return item.relativePath;
134	  const base = (item.path ?? "").split(/[\\/]/).pop();
135	  return base || item.name || item.path || "";
136	}
137	
138	function rejectionReasons(
139	  rejections: { reason: string }[] | undefined,
140	): string[] {
141	  const out: string[] = [];
142	  for (const entry of rejections ?? []) {
143	    const reason = entry?.reason?.trim();
144	    if (reason && !out.includes(reason)) out.push(reason);
145	  }
146	  return out;
147	}
148	
149	/**
150	 * Candidates without a `path` are dropped: the command imports by path, so a
151	 * pathless record could never be sent and would only render as a dead row.
152	 */
153	export function toSonarrCandidates(
154	  items: SonarrManualImportItem[] | undefined,
155	): ManualImportCandidate[] {
156	  return (items ?? [])
157	    .filter((item) => !!item.path)
158	    .map((item) => ({
159	      id: item.id,
160	      path: item.path!,
161	      folderName: item.folderName,
162	      name: fileName(item),
163	      size: item.size ?? 0,
164	      mediaId: item.series?.id,
165	      mediaTitle: item.series?.title,
166	      seasonNumber: item.seasonNumber,
167	      episodeIds: (item.episodes ?? []).map((e) => e.id),
168	      episodeFileId: item.episodeFileId,
169	      releaseType: item.releaseType,
170	      quality: item.quality,
171	      languages: item.languages ?? [],
172	      releaseGroup: item.releaseGroup,
173	      indexerFlags: item.indexerFlags ?? 0,
174	      rejections: rejectionReasons(item.rejections),
175	    }));
176	}
177	
178	export function toRadarrCandidates(
179	  items: RadarrManualImportItem[] | undefined,
180	): ManualImportCandidate[] {
181	  return (items ?? [])
182	    .filter((item) => !!item.path)
183	    .map((item) => ({
184	      id: item.id,
185	      path: item.path!,
186	      folderName: item.folderName,
187	      name: fileName(item),
188	      size: item.size ?? 0,
189	      mediaId: item.movie?.id,
190	      mediaTitle: item.movie?.title,
191	      episodeIds: [],
192	      quality: item.quality,
193	      languages: item.languages ?? [],
194	      releaseGroup: item.releaseGroup,
195	      indexerFlags: item.indexerFlags ?? 0,
196	      rejections: rejectionReasons(item.rejections),
197	    }));
198	}
