200	/**
201	 * The rows *arr already resolved by itself — exactly what one-tap force import
202	 * (#325) sends. A Sonarr file needs a series, at least one episode and a parsed
203	 * quality; a Radarr file needs a movie and a quality. Anything short of that
204	 * has to be mapped on the manual-import screen instead.
205	 */
206	export function autoRows(
207	  service: ManualImportService,
208	  candidates: ManualImportCandidate[],
209	): ManualImportRow[] {
210	  const rows: ManualImportRow[] = [];
211	  for (const candidate of candidates) {
212	    if (!candidate.mediaId || !candidate.quality) continue;
213	    if (service === "sonarr" && candidate.episodeIds.length === 0) continue;
214	    rows.push({
215	      candidate,
216	      mediaId: candidate.mediaId,
217	      quality: candidate.quality,
218	      episodeIds: candidate.episodeIds,
219	    });
220	  }
221	  return rows;
222	}
223	
224	/**
225	 * The starting mapping for the manual-import screen: what *arr already
226	 * resolved by itself, plus which files begin selected.
227	 *
228	 * The destination is screen-wide — one series or movie for the whole download
229	 * folder — so a file's episode ids are only carried over when that file matched
230	 * THAT destination. A folder holding two series would otherwise pair one file's
231	 * episode ids with the other file's seriesId, and the command would import into
232	 * the wrong show. Files matched to something else start unmapped, for the user
233	 * to map by hand or leave out.
234	 */
235	export function seedMapping(candidates: ManualImportCandidate[]): {
236	  mediaId?: number;
237	  episodeIds: Record<number, number[]>;
238	  included: Record<number, boolean>;
239	} {
240	  const mediaId = candidates.find((c) => c.mediaId)?.mediaId;
241	  return { mediaId, ...seedForDestination(candidates, mediaId) };
242	}
243	
244	/**
245	 * The per-file mapping for one destination: the episodes *arr matched to it,
246	 * and which files start selected. Also what the screen re-seeds from when the
247	 * user picks another destination on a folder import, where files matched to
248	 * the previous title must not ride along into the new one.
249	 *
250	 * Radarr has no per-file mapping to imply intent, so inclusion is explicit:
251	 * start from the files matched to the destination, or the largest UNMATCHED
252	 * one when none were (sample and subtitle files are exactly what the user
253	 * deselects). A file matched to some other title is never picked as that
254	 * fallback, since it would be imported under the wrong movie.
255	 */
256	export function seedForDestination(
257	  candidates: ManualImportCandidate[],
258	  mediaId: number | undefined,
259	): {
260	  episodeIds: Record<number, number[]>;
261	  included: Record<number, boolean>;
262	} {
263	  const onTarget =
264	    mediaId === undefined ? [] : candidates.filter((c) => c.mediaId === mediaId);
265	
266	  const seedIncluded = onTarget.length
267	    ? onTarget
268	    : candidates
269	        .filter((c) => c.mediaId === undefined)
270	        .sort((a, b) => b.size - a.size)
271	        .slice(0, 1);
272	
273	  return {
274	    episodeIds: Object.fromEntries(
275	      onTarget.filter((c) => c.episodeIds.length).map((c) => [c.id, c.episodeIds]),
276	    ),
277	    included: Object.fromEntries(seedIncluded.map((c) => [c.id, true])),
278	  };
279	}
280	
281	/**
282	 * Payload mirroring Sonarr's web UI (InteractiveImportModalContent). The
283	 * per-file `downloadId` is what ties the import back to the queue item, so the
284	 * grab leaves the queue instead of lingering as a second stuck entry.
285	 */
286	export function sonarrImportFiles(
287	  rows: ManualImportRow[],
288	  downloadId?: string,
289	): SonarrManualImportFile[] {
290	  return rows.map((row) => ({
291	    path: row.candidate.path,
292	    folderName: row.candidate.folderName,
293	    seriesId: row.mediaId,
294	    episodeIds: row.episodeIds,
295	    quality: row.quality,
296	    languages: row.candidate.languages,
297	    releaseGroup: row.candidate.releaseGroup,
298	    indexerFlags: row.candidate.indexerFlags,
299	    releaseType: row.candidate.releaseType,
300	    episodeFileId: row.candidate.episodeFileId,
301	    downloadId,
302	  }));
303	}
304	
305	export function radarrImportFiles(
306	  rows: ManualImportRow[],
307	  downloadId?: string,
308	): RadarrManualImportFile[] {
309	  return rows.map((row) => ({
310	    path: row.candidate.path,
311	    folderName: row.candidate.folderName,
312	    movieId: row.mediaId,
313	    quality: row.quality,
314	    languages: row.candidate.languages,
315	    releaseGroup: row.candidate.releaseGroup,
316	    indexerFlags: row.candidate.indexerFlags,
317	    downloadId,
318	  }));
319	}
320	
321	// The rejection a folder scan puts on a file whose title is not in the library
322	// (ManualImportService.ProcessFile, ImportRejectionReason.UnknownMovie /
323	// UnknownSeries). Server-side English constants, not localized.
324	const UNKNOWN_TITLE_REJECTION: Record<ManualImportService, string> = {
325	  radarr: "Unknown Movie",
326	  sonarr: "Unknown Series",
327	};
328	
329	/**
330	 * Whether any file was refused because *arr has no such movie or series. A
331	 * folder can hold a title the user never added; the screen can only map files
332	 * to titles already in the library, so it points them at Search instead.
333	 */
334	export function hasUnknownTitle(
335	  service: ManualImportService,
336	  candidates: ManualImportCandidate[],
337	): boolean {
338	  const reason = UNKNOWN_TITLE_REJECTION[service];
339	  return candidates.some((c) => c.rejections.includes(reason));
340	}
341	
342	/**
343	 * Files *arr matched to some title other than the chosen destination that the
344	 * import will leave out. The screen imports into one title per pass, so a
345	 * folder holding two movies needs a second pass for the other one. A file the
346	 * user mapped by hand anyway is in `rows` and not counted.
347	 */
348	export function countMatchedElsewhere(
349	  candidates: ManualImportCandidate[],
350	  mediaId: number | undefined,
351	  rows: ManualImportRow[],
352	): number {
353	  if (mediaId === undefined) return 0;
354	  const importing = new Set(rows.map((row) => row.candidate.id));
355	  return candidates.filter(
356	    (c) =>
357	      c.mediaId !== undefined && c.mediaId !== mediaId && !importing.has(c.id),
358	  ).length;
359	}
360	
361	/** "WEBDL-1080p", with the proper/repack revision appended when there is one. */
362	export function qualityLabel(quality: ArrQualityModel | undefined): string {
363	  if (!quality?.quality?.name) return "Unknown quality";
364	  const version = quality.revision?.version ?? 1;
365	  if (quality.revision?.isRepack) return `${quality.quality.name} REPACK`;
366	  if (version > 1) return `${quality.quality.name} PROPER`;
367	  return quality.quality.name;
368	}
369	
370	/**
371	 * A quality picked from `/qualitydefinition` carries no revision, so give it
372	 * the neutral one the parser would have produced for a first release.
373	 */
374	export function qualityFromDefinition(quality: {
375	  id: number;
376	  name: string;
377	  source?: string;
378	  resolution?: number;
379	}): ArrQualityModel {
380	  return { quality, revision: { version: 1, real: 0, isRepack: false } };
381	}

