193	  // ignored by the resolver — they don't need to be cleaned eagerly, except
194	  // on instance delete (we prune to keep storage tidy).
195	  activeInstance?: Partial<Record<ServiceId, string>>;
196	  // v29: optional per-workspace home-network selection (#148). Missing/undefined
197	  // means "use ALL home networks" (the default), mirroring how
198	  // `attachedInstances === undefined` means auto-attach. An explicit array
199	  // selects a subset of the GLOBAL homeNetworks by id — ids that no longer match
200	  // a live network are ignored at resolve time, and an empty array means "no
201	  // home network for this workspace → always remote". Home networks themselves
202	  // are created/edited/deleted only on the Home Networks screen; this is purely
203	  // which of them attach to this workspace. The *active* dashboard's selection
204	  // drives the global away flag (see resolveEffectiveHomeNetworks /
205	  // evaluateHomeNetwork in lib/network.ts); an instance attached only to other
206	  // dashboards is judged against their selections instead (the store's
207	  // resolveInstanceNetwork, #418).
208	  homeNetworkIds?: string[];
209	  // v30: optional per-workspace Services-tab tile order. Missing/undefined means
210	  // "use the global servicesOrder" so existing dashboards keep the shared order.
211	  // Unknown ids are skipped at render time; kinds missing from the list fall in
212	  // at the end in canonical order (same forgiving semantics as the global
213	  // servicesOrder), so adding a new service kind never hides it.
214	  servicesOrder?: ServiceId[];
215	  // v37: optional per-workspace overrides for the middle bottom-tab icons
216	  // (#195). Keys are TabRouteIds, values lucide names from the curated
217	  // registry in lib/dashboard-icons. A missing key (or unknown icon name)
218	  // falls back to the default at render time via resolveTabIcon, so only
219	  // actual overrides are stored — picking the default removes the entry.
220	  // Kept loose (string/string) like `icon`/`pinnedTabs` so entries survive
221	  // app upgrades that add/remove tabs or icons.
222	  tabIcons?: Record<string, string>;
223	}
224	
225	// Legacy widget-settings shape carried by v13 exports. v13→v14 migration folds
226	// these into per-slot settings on the auto-built Default dashboard. We still
227	// export the type so the v14 export migration can reference it.
228	export type WidgetSettingsMap = Partial<Record<WidgetId, Record<string, unknown>>>;
229	
230	// Notification preferences (v2+). Lives on the config store so it hydrates
231	// after initStorage() completes — the old standalone notifications-store
232	// hydrated synchronously before the AsyncStorage cache was populated, which
233	// caused the "enabled" toggle to revert to `true` on every cold start.
234	// Notification categories that can be toggled per-event-type. Kept as a
235	// string-literal union next to NotificationSettings so adding/removing a
236	// category is a single source of truth.
237	export type NotifCategory =
238	  | "torrentCompleted"
239	  | "sabnzbdCompleted"
240	  | "nzbgetCompleted"
241	  | "radarrDownloaded"
242	  | "sonarrDownloaded"
243	  // v61 (#464): a release sent to the download client, from the Radarr/Sonarr
244	  // Grab webhook, the backend history poller or the in-app watcher. Off by
245	  // default: grabs are far chattier than imports.
246	  | "radarrGrabbed"
247	  | "sonarrGrabbed"
248	  | "serviceOffline"
249	  | "overseerrNewRequest"
250	  // Tracearr webhook events. Exposed per-instance only (in each Tracearr
251	  // instance's editor) — no global toggle rows — so the per-instance override
252	  // is the primary control; these globals are the inherit/fallback defaults.
253	  | "tracearrViolation"
254	  | "tracearrNewDevice"
255	  | "tracearrTrustScore"
256	  | "tracearrServerDown"
257	  | "tracearrServerUp"
258	  | "tracearrStreamStarted"
259	  | "tracearrStreamStopped"
260	  // v62 (#486): Cleanuparr events from the backend poller, QueueItemDeleted
261	  // ("Download removed") and DownloadCleaned ("Download cleaned"). Exposed
262	  // per-instance only, like the Tracearr ones; no in-app watcher.
263	  | "cleanuparrRemoved"
264	  | "cleanuparrCleaned";
265	
266	// v34 (issue #220): optional Apprise sink. Persistent config-key model — the
267	// user configures their service URLs in the Apprise server's own UI under a key
268	// and stores only the full notify endpoint (e.g. http://host:8000/notify/
269	// dashboarr) plus an optional tag filter here. No service secrets live in the app.
270	export interface AppriseConfig {
271	  enabled: boolean;
272	  url: string;
273	  tags: string;
274	}
275	
276	export interface NotificationSettings {
277	  enabled: boolean;
278	  torrentCompleted: boolean;
279	  sabnzbdCompleted: boolean;
280	  nzbgetCompleted: boolean;
281	  radarrDownloaded: boolean;
282	  sonarrDownloaded: boolean;
283	  radarrGrabbed: boolean;
284	  sonarrGrabbed: boolean;
285	  serviceOffline: boolean;
286	  overseerrNewRequest: boolean;
287	  tracearrViolation: boolean;
288	  tracearrNewDevice: boolean;
289	  tracearrTrustScore: boolean;
290	  tracearrServerDown: boolean;
291	  tracearrServerUp: boolean;
292	  tracearrStreamStarted: boolean;
293	  tracearrStreamStopped: boolean;
294	  cleanuparrRemoved: boolean;
295	  cleanuparrCleaned: boolean;
296	  // v21: per-instance overrides keyed by instance UUID. A category absent from
297	  // an instance's override map falls through to the global toggle. Allows
298	  // "notify me from the primary Radarr but stay silent from the testing one"
299	  // without splitting the global toggles per kind.
300	  perInstance?: Record<string, Partial<Record<NotifCategory, boolean>>>;
301	  // v34: Apprise notification sink (additive to Expo push). undefined = unset.
302	  apprise?: AppriseConfig;
303	  // v42 (issue #310): per-qBittorrent-instance muted category names for the
304	  // torrentCompleted notification (e.g. cross-seed's injection category).
305	  // Keyed by instance UUID; "" mutes uncategorized torrents. Matching is exact
306	  // and case-sensitive. Absent/empty = notify for everything.
307	  qbtMutedCategories?: Record<string, string[]>;
308	}
309	
310	
311	
312	export interface ExportPayload {
313	  version: number;
314	  exportedAt: string;
315	  // v13: array of ServiceInstance per kind, each carrying a UUID id.
316	  services: Record<ServiceId, ServiceInstance[]>;
317	  // v13: keyed by instance UUID, not ServiceId.
318	  secrets: Record<string, ServiceSecrets>;
319	  autoSwitchNetwork: boolean;
320	  // v11 — replaces homeSSID/homeBSSID with a per-AP list so mesh setups can
321	  // register every SSID/BSSID pair the user considers "home".
322	  homeNetworks: HomeNetwork[];
323	  // v14: per-user named dashboards with per-slot settings. Replaces the v7-v13
324	  // `dashboardWidgets: WidgetId[]` + `widgetSettings: Record<WidgetId, …>`.
325	  dashboards: Dashboard[];
326	  activeDashboardId: string;
327	  // v2 (v49: + ignoreCertErrors)
328	  backend?: {
329	    url: string | null;
330	    sharedSecret: string | null;
331	    deviceId: string | null;
332	    ignoreCertErrors?: boolean;
333	  };
334	  notificationSettings?: NotificationSettings;
335	  // v4
336	  wolDevices?: WakeOnLanDevice[];
337	  // v8
338	  hapticsEnabled?: boolean;
339	  // v10
340	  globalCustomHeaders?: Record<string, string>;
341	  // v12
342	  uiScale?: UiScale;
343	  // v17 — user-defined Services tab tile order.
344	  servicesOrder?: ServiceId[];
345	  // v32 — opt-in "VPN connected counts as home" (#185).
346	  treatVpnAsHome?: boolean;
347	  // v38 — global app theme preset.
348	  appTheme?: AppThemeId;
349	  // v40 — calendar first-day-of-week preference (#320).
350	  weekStart?: WeekStart;
351	  // v56 — user-defined web shortcuts for the Shortcuts widget (#344).
352	  shortcuts?: WebShortcut[];
353	}

