1	import {
2	  SERVICE_IDS,
3	  DASHBOARD_WIDGET_IDS,
4	  UI_SCALES,
5	  MAX_HOME_NETWORKS,
6	} from "@/lib/constants";
7	import type { ServiceId, WidgetId } from "@/lib/constants";
8	import type {
9	  Dashboard,
10	  ExportPayload,
11	  HomeNetwork,
12	  ServiceInstance,
13	  ServiceSecrets,
14	  WakeOnLanDevice,
15	  WebShortcut,
16	  WidgetSlot,
17	} from "@/lib/config-types";
18	import type { NotificationSettings, NotifCategory, AppriseConfig } from "@/lib/config-types";
19	import { isValidWeekStart } from "@/lib/week-start-values";
20	import { NOTIF_CATEGORIES } from "@/lib/notification-categories";
21	import { isValidAppTheme } from "@/lib/app-themes";
22	import { ALL_PICKABLE_TABS, MAX_PINNED_TABS } from "@/lib/tab-routes";
23	import { isSeerrAuthMode } from "@/lib/seerr-auth";
24	import { isValidShortcutUrl, SHORTCUT_NAME_MAX_LENGTH } from "@/lib/web-shortcuts";
25	
26	const NOTIF_CATEGORY_SET: ReadonlySet<string> = new Set(NOTIF_CATEGORIES);
27	
28	const SERVICE_ID_SET: ReadonlySet<string> = new Set(SERVICE_IDS);
29	const PICKABLE_TAB_SET: ReadonlySet<string> = new Set(ALL_PICKABLE_TABS);
30	const WIDGET_ID_SET: ReadonlySet<string> = new Set(DASHBOARD_WIDGET_IDS);
31	
32	// Accepts the 8 hex characters palette swatches use. Restrictive on purpose —
33	// rejects "transparent", named colors, and rgba() so the field stays a stable
34	// JSON-serializable string the picker can map back to a palette entry.
35	const HEX_COLOR_RE = /^#[0-9a-fA-F]{6}$/;
36	
37	function isPlainObject(v: unknown): v is Record<string, unknown> {
38	  return typeof v === "object" && v !== null && !Array.isArray(v);
39	}
40	
41	function isHttpUrlOrEmpty(v: unknown): v is string {
42	  if (typeof v !== "string") return false;
43	  if (v === "") return true;
44	  try {
45	    const u = new URL(v);
46	    return u.protocol === "http:" || u.protocol === "https:";
47	  } catch {
48	    return false;
49	  }
50	}
51	
52	// RFC 7230 token chars — same set the spec allows in field-name. Rejecting
53	// CR/LF in values closes off header-injection if someone hand-edits an export.
54	const HEADER_NAME_RE = /^[A-Za-z0-9!#$%&'*+\-.^_`|~]+$/;
55	const MAX_HEADERS_PER_SCOPE = 32;
56	
57	function coerceHeaderMap(v: unknown): Record<string, string> | null {
58	  if (!isPlainObject(v)) return null;
59	  const out: Record<string, string> = {};
60	  let count = 0;
61	  for (const [key, value] of Object.entries(v)) {
62	    if (typeof key !== "string" || key.length === 0 || key.length > 200) return null;
63	    if (!HEADER_NAME_RE.test(key)) return null;
64	    if (typeof value !== "string" || value.length > 4096) return null;
65	    if (/[\r\n]/.test(value)) return null;
66	    out[key] = value;
67	    if (++count > MAX_HEADERS_PER_SCOPE) return null;
68	  }
69	  return out;
70	}
71	
72	function coerceServiceInstance(v: unknown): ServiceInstance | null {
73	  if (!isPlainObject(v)) return null;
74	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
75	  if (typeof v.enabled !== "boolean") return null;
76	  if (typeof v.name !== "string" || v.name.length > 200) return null;
77	  if (!isHttpUrlOrEmpty(v.localUrl)) return null;
78	  if (!isHttpUrlOrEmpty(v.remoteUrl)) return null;
79	  if (typeof v.useRemote !== "boolean") return null;
80	  const out: ServiceInstance = {
81	    id: v.id,
82	    enabled: v.enabled,
83	    name: v.name,
84	    localUrl: v.localUrl,
85	    remoteUrl: v.remoteUrl,
86	    useRemote: v.useRemote,
87	    // v23: optional. Coerce to a strict boolean so a missing/garbage value
88	    // (older exports, hand-edited files) lands on the secure default.
89	    ignoreCertErrors: v.ignoreCertErrors === true,
90	  };
91	  // v36 (#287): optional per-instance arr add-flow defaults. Drop invalid
92	  // values rather than rejecting the whole instance — absence just falls back
93	  // to first-in-list at add time.
94	  if (isPositiveInt(v.defaultQualityProfileId)) {
95	    out.defaultQualityProfileId = v.defaultQualityProfileId;
96	  }
97	  if (isPositiveInt(v.defaultMetadataProfileId)) {
98	    out.defaultMetadataProfileId = v.defaultMetadataProfileId;
99	  }
100	  if (
101	    typeof v.defaultRootFolderPath === "string" &&
102	    v.defaultRootFolderPath.length > 0 &&
103	    v.defaultRootFolderPath.length <= 1024
104	  ) {
105	    out.defaultRootFolderPath = v.defaultRootFolderPath;
106	  }
107	  // v41 (#289): optional qBittorrent-only add-flow tagging. Only persisted
108	  // when explicitly enabled — absence (or garbage) means off.
109	  if (v.tagAddedTorrents === true) {
110	    out.tagAddedTorrents = true;
111	  }
112	  // v60 (#394): optional "Remote URL needs a VPN" flag. Same shape rule as
113	  // tagAddedTorrents: only persisted when explicitly on, garbage means off.
114	  if (v.remoteRequiresVpn === true) {
115	    out.remoteRequiresVpn = true;
116	  }
117	  // v52 (#332): optional Seerr "Request As" default. Seerr user ids are
118	  // positive auto-increment integers. This was missing from the coercer when
119	  // v52 shipped, so an export/import round-trip silently dropped it.
120	  if (isPositiveInt(v.requestAsUserId)) {
121	    out.requestAsUserId = v.requestAsUserId;
122	  }
123	  // v53 (#332): optional Seerr sign-in mode. "apiKey" is dropped on purpose so
124	  // the stored shape stays "absent means API key"; garbage is dropped too.
125	  if (isSeerrAuthMode(v.authMode) && v.authMode !== "apiKey") {
126	    out.authMode = v.authMode;
127	  }
128	  // v57 (#386): optional unRAID → Glances disk I/O pairing. Same id shape as
129	  // ServiceInstance.id. An id pointing at an instance that isn't in this
130	  // payload is kept — the editor resolves it at render time and shows it as
131	  // unknown, matching how requestAsUserId handles a deleted Seerr account.
132	  if (
133	    typeof v.diskIoInstanceId === "string" &&
134	    v.diskIoInstanceId.length > 0 &&
135	    v.diskIoInstanceId.length <= 128
136	  ) {
137	    out.diskIoInstanceId = v.diskIoInstanceId;
138	  }
139	  // v61: optional Bazarr → Radarr/Sonarr links. Same id shape (plus the
140	  // ARR_LINK_OFF sentinel, which fits it); a dangling id is kept for the same
141	  // reason as diskIoInstanceId.
142	  for (const key of ["linkedRadarrInstanceId", "linkedSonarrInstanceId"] as const) {
143	    const id = v[key];
144	    if (typeof id === "string" && id.length > 0 && id.length <= 128) {
145	      out[key] = id;
146	    }
147	  }
148	  return out;
149	}
150	
151	function isPositiveInt(v: unknown): v is number {
152	  return typeof v === "number" && Number.isInteger(v) && v > 0;
153	}
154	
155	function coerceServiceSecrets(v: unknown): ServiceSecrets | null {
156	  if (!isPlainObject(v)) return null;
157	  const out: ServiceSecrets = {};
158	  for (const key of ["apiKey", "username", "password"] as const) {
159	    const raw = v[key];
160	    if (raw === undefined || raw === null) continue;
161	    if (typeof raw !== "string" || raw.length > 4096) return null;
162	    out[key] = raw;
163	  }
164	  if (v.customHeaders !== undefined && v.customHeaders !== null) {
165	    const headers = coerceHeaderMap(v.customHeaders);
166	    if (!headers) return null;
167	    if (Object.keys(headers).length > 0) out.customHeaders = headers;
168	  }
169	  return out;
170	}
171	
172	function coerceWolDevice(v: unknown): WakeOnLanDevice | null {
173	  if (!isPlainObject(v)) return null;
174	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
175	  if (typeof v.name !== "string" || v.name.length > 200) return null;
176	  if (typeof v.mac !== "string" || v.mac.length > 32) return null;
177	  const out: WakeOnLanDevice = { id: v.id, name: v.name, mac: v.mac };
178	  if (v.broadcastAddress !== undefined) {
179	    if (typeof v.broadcastAddress !== "string" || v.broadcastAddress.length > 45) return null;
180	    out.broadcastAddress = v.broadcastAddress;
181	  }
182	  if (v.port !== undefined) {
183	    if (typeof v.port !== "number" || !Number.isInteger(v.port) || v.port < 1 || v.port > 65535) {
184	      return null;
185	    }
186	    out.port = v.port;
187	  }
188	  return out;
189	}
190	
191	function coerceWebShortcut(v: unknown): WebShortcut | null {
192	  if (!isPlainObject(v)) return null;
193	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
194	  if (
195	    typeof v.name !== "string" ||
196	    v.name.trim().length === 0 ||
197	    v.name.length > SHORTCUT_NAME_MAX_LENGTH
198	  ) {
199	    return null;
200	  }
201	  if (typeof v.url !== "string" || !isValidShortcutUrl(v.url)) return null;
202	  const out: WebShortcut = { id: v.id, name: v.name, url: v.url };
203	  // Icon and color are looked up leniently at render time (unknown values fall
204	  // back to defaults), so only reject present-but-malformed values here.
205	  if (v.icon !== undefined && v.icon !== null) {
206	    if (typeof v.icon !== "string" || v.icon.length > 64) return null;
207	    out.icon = v.icon;
208	  }
209	  if (v.color !== undefined && v.color !== null) {
210	    if (typeof v.color !== "string" || !/^#[0-9a-f]{6}$/i.test(v.color)) return null;
211	    out.color = v.color;
212	  }
213	  return out;
214	}
215	
216	function coerceHomeNetwork(v: unknown): HomeNetwork | null {
217	  if (!isPlainObject(v)) return null;
218	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
219	  if (typeof v.ssid !== "string" || v.ssid.length === 0 || v.ssid.length > 64) return null;
220	  if (typeof v.bssid !== "string" || v.bssid.length > 64) return null;
221	  return { id: v.id, ssid: v.ssid, bssid: v.bssid };
222	}
223	
224	function coerceWidgetSlot(v: unknown): WidgetSlot | null {
225	  if (!isPlainObject(v)) return null;
226	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
227	  if (typeof v.widgetId !== "string") return null;
228	  if (!WIDGET_ID_SET.has(v.widgetId)) return null;
229	  const slot: WidgetSlot = { id: v.id, widgetId: v.widgetId as WidgetId };
230	  if (v.settings !== undefined && v.settings !== null) {
231	    if (!isPlainObject(v.settings)) return null;
232	    slot.settings = v.settings as Record<string, unknown>;
233	  }
234	  return slot;
235	}
236	
237	function coerceDashboard(v: unknown): Dashboard | null {
238	  if (!isPlainObject(v)) return null;
239	  if (typeof v.id !== "string" || v.id.length === 0 || v.id.length > 128) return null;
240	  if (typeof v.name !== "string" || v.name.length === 0 || v.name.length > 200) return null;
241	  if (!Array.isArray(v.widgets)) return null;
242	  const widgets: WidgetSlot[] = [];
243	  for (const w of v.widgets) {
244	    const slot = coerceWidgetSlot(w);
245	    if (!slot) continue;
246	    widgets.push(slot);
247	  }
248	  const out: Dashboard = { id: v.id, name: v.name, widgets };
249	  // v20: optional identity + workspace fields. Each is rejected only when
250	  // present-but-malformed; absent fields fall back at render time via the
251	  // resolve helpers, so old payloads validate cleanly.
252	  if (v.icon !== undefined && v.icon !== null) {
253	    if (typeof v.icon !== "string" || v.icon.length === 0 || v.icon.length > 64) {
254	      return null;
255	    }
256	    out.icon = v.icon;
257	  }
258	  if (v.color !== undefined && v.color !== null) {
259	    if (typeof v.color !== "string" || !HEX_COLOR_RE.test(v.color)) return null;
260	    out.color = v.color;
261	  }
262	  if (v.attachedInstances !== undefined && v.attachedInstances !== null) {
263	    if (!Array.isArray(v.attachedInstances)) return null;
264	    const seen = new Set<string>();
265	    const attached: string[] = [];
266	    for (const id of v.attachedInstances) {
267	      // Instance UUIDs aren't validated against a known set here (they're
268	      // user-generated and may legitimately reference instances that don't
269	      // exist on this device yet — e.g. cross-device import). Render-side
270	      // intersects with live instances; non-matches are silently ignored.
271	      if (typeof id !== "string" || id.length === 0 || id.length > 128) continue;
272	      if (seen.has(id)) continue;
273	      seen.add(id);
274	      attached.push(id);
275	    }
276	    out.attachedInstances = attached;
277	  }
278	  if (v.pinnedTabs !== undefined && v.pinnedTabs !== null) {
279	    if (!Array.isArray(v.pinnedTabs)) return null;
280	    const seen = new Set<string>();
281	    const pinned: string[] = [];
282	    for (const tab of v.pinnedTabs) {
283	      if (typeof tab !== "string" || tab.length === 0 || tab.length > 64) continue;
284	      if (seen.has(tab)) continue;
285	      seen.add(tab);
286	      pinned.push(tab);
287	      if (pinned.length >= MAX_PINNED_TABS) break;
288	    }
289	    out.pinnedTabs = pinned;
290	  }
291	  // v22: per-workspace active instance pin per kind. Stored UUIDs that point
292	  // at instances the device doesn't currently have are kept — the resolver
293	  // tolerates staleness, and cross-device imports may legitimately carry
294	  // unknown UUIDs.
295	  if (v.activeInstance !== undefined && v.activeInstance !== null) {
296	    if (!isPlainObject(v.activeInstance)) return null;
297	    const cleaned: Partial<Record<ServiceId, string>> = {};
298	    for (const [kind, raw] of Object.entries(v.activeInstance)) {
299	      if (!(SERVICE_IDS as readonly string[]).includes(kind)) continue;
300	      if (typeof raw !== "string" || raw.length === 0 || raw.length > 128) continue;
301	      cleaned[kind as ServiceId] = raw;
302	    }
303	    if (Object.keys(cleaned).length > 0) {
304	      out.activeInstance = cleaned;
305	    }
306	  }
307	  // v29: optional per-workspace home-network selection (#148). Present-but-not-
308	  // array is rejected; otherwise dedupe + drop empties (import-tolerant, like
309	  // attachedInstances), and cap at MAX_HOME_NETWORKS. Ids aren't validated
310	  // against the live list — the resolver ignores stale ids. An explicit empty
311	  // array is preserved — it's a valid selection ("no home network here").
312	  if (v.homeNetworkIds !== undefined && v.homeNetworkIds !== null) {
313	    if (!Array.isArray(v.homeNetworkIds)) return null;
314	    const seen = new Set<string>();
315	    const ids: string[] = [];
316	    for (const id of v.homeNetworkIds) {
317	      if (typeof id !== "string" || id.length === 0 || id.length > 128) continue;
318	      if (seen.has(id)) continue;
319	      seen.add(id);
320	      ids.push(id);
321	      if (ids.length >= MAX_HOME_NETWORKS) break;
322	    }
323	    out.homeNetworkIds = ids;
324	  }
325	  // v30: optional per-workspace Services-tab order. Present-but-not-array is
326	  // rejected; otherwise dedupe + drop unknown service ids (forward-compat, like
327	  // the global servicesOrder). Absence means "use the global order".
328	  if (v.servicesOrder !== undefined && v.servicesOrder !== null) {
329	    if (!Array.isArray(v.servicesOrder)) return null;
330	    const seen = new Set<string>();
331	    const order: ServiceId[] = [];
332	    for (const sid of v.servicesOrder) {
