366	  // the key existed validates cleanly; the missing entry falls back to its
367	  // default at hydrate time.
368	  const requiredKeys = [
369	    "enabled",
370	    "torrentCompleted",
371	    "radarrDownloaded",
372	    "sonarrDownloaded",
373	    "serviceOffline",
374	    "overseerrNewRequest",
375	  ] as const;
376	  const optionalKeys = [
377	    "sabnzbdCompleted",
378	    "nzbgetCompleted",
379	    "radarrGrabbed",
380	    "sonarrGrabbed",
381	    "tracearrViolation",
382	    "tracearrNewDevice",
383	    "tracearrTrustScore",
384	    "tracearrServerDown",
385	    "tracearrServerUp",
386	    "tracearrStreamStarted",
387	    "tracearrStreamStopped",
388	    "cleanuparrRemoved",
