     1	/**
     2	 * Pure helpers for the user-defined web shortcuts (#344): validation and
     3	 * normalization of the URL a shortcut opens. Bundled into the backend's web
     4	 * editor through store/config-schema, so no React Native, Expo or store
     5	 * imports here.
     6	 */
     7	
     8	export const SHORTCUT_NAME_MAX_LENGTH = 100;
     9	export const SHORTCUT_URL_MAX_LENGTH = 2048;
    10	
    11	/**
    12	 * Auto-prefix `https://` when the user typed a bare host such as
    13	 * `portainer.example.com` or `192.168.1.10:9000`. Services default to http://
    14	 * (a LAN box usually has no TLS), but a shortcut opens in the system browser
    15	 * where a wrong scheme just shows an error page the user can fix from the
    16	 * address bar, so the secure default is the better guess.
    17	 */
    18	export function normalizeShortcutUrl(raw: string): string {
    19	  const trimmed = raw.trim();
    20	  if (trimmed === "") return "";
    21	  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(trimmed)) return trimmed;
    22	  return `https://${trimmed}`;
    23	}
    24	
    25	/**
    26	 * Only `http:` and `https:` URLs may be stored. Anything else (`javascript:`,
    27	 * `file:`, custom app schemes) is rejected so a shortcut can never hand the
    28	 * in-app browser something other than a web page. Length-capped so a pasted
    29	 * blob can't bloat the config export.
    30	 */
    31	export function isValidShortcutUrl(url: string): boolean {
    32	  if (typeof url !== "string") return false;
    33	  if (url.length === 0 || url.length > SHORTCUT_URL_MAX_LENGTH) return false;
    34	  if (!/^https?:\/\//i.test(url)) return false;
    35	  let parsed: URL;
    36	  try {
    37	    parsed = new URL(url);
    38	  } catch {
    39	    return false;
    40	  }
    41	  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return false;
    42	  return parsed.hostname.length > 0;
    43	}
    44	
    45	export type ShortcutUrlValidation =
    46	  | { kind: "ok"; url: string }
    47	  | { kind: "invalid"; message: string };
    48	
    49	/** Normalize then validate what the user typed in the URL field. */
    50	export function validateShortcutUrl(raw: string): ShortcutUrlValidation {
    51	  const url = normalizeShortcutUrl(raw);
    52	  if (url === "") return { kind: "invalid", message: "URL is required" };
    53	  if (url.length > SHORTCUT_URL_MAX_LENGTH) {
    54	    return { kind: "invalid", message: "URL is too long" };
    55	  }
    56	  if (!/^https?:\/\//i.test(url)) {
    57	    return {
    58	      kind: "invalid",
    59	      message: "Only http:// and https:// links can be opened",
    60	    };
    61	  }
    62	  if (!isValidShortcutUrl(url)) return { kind: "invalid", message: "Not a valid URL" };
    63	  return { kind: "ok", url };
    64	}
    65	
    66	/** Host shown under a shortcut's name in the management list. */
    67	export function shortcutHostLabel(url: string): string {
    68	  try {
    69	    const parsed = new URL(url);
    70	    return parsed.host || url;
    71	  } catch {
    72	    return url;
    73	  }
    74	}
