     1	export type UrlValidation =
     2	  | { kind: "ok" }
     3	  | { kind: "invalid"; message: string }
     4	  | { kind: "warn"; message: string };
     5	
     6	/**
     7	 * Validate a service URL before saving.
     8	 *
     9	 * - Empty string is allowed (user hasn't configured that URL yet).
    10	 * - Only `http:` and `https:` schemes are accepted; anything else is rejected
    11	 *   outright (blocks `javascript:`, `file:`, `gopher:` etc. from ever reaching
    12	 *   the fetch layer).
    13	 * - For `remote` URLs, `http://` produces a `warn` — the caller should
    14	 *   confirm with the user before saving, since API keys will be sent in the
    15	 *   clear over the public internet.
    16	 * - For `local` URLs, `http://` is fine (typical LAN setups don't have TLS).
    17	 */
    18	export function validateServiceUrl(
    19	  raw: string,
    20	  kind: "local" | "remote",
    21	): UrlValidation {
    22	  const trimmed = raw.trim();
    23	  if (trimmed === "") return { kind: "ok" };
    24	
    25	  let parsed: URL;
    26	  try {
    27	    parsed = new URL(trimmed);
    28	  } catch {
    29	    return { kind: "invalid", message: "Not a valid URL" };
    30	  }
    31	
    32	  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    33	    return {
    34	      kind: "invalid",
    35	      message: `URL scheme ${parsed.protocol} is not allowed. Use http:// or https://.`,
    36	    };
    37	  }
    38	
    39	  if (kind === "remote" && parsed.protocol === "http:") {
    40	    return {
    41	      kind: "warn",
    42	      message:
    43	        "This remote URL uses http:// — API keys and credentials will be sent in cleartext over the internet. Use https:// for remote endpoints whenever possible.",
    44	    };
    45	  }
    46	
    47	  return { kind: "ok" };
    48	}
    49	
    50	/**
    51	 * Auto-prefix `http://` if no protocol is present. This helps users who type
    52	 * just `192.168.1.10:8080` or `localhost:8989`.
    53	 */
    54	export function normalizeServiceUrl(raw: string): string {
    55	  const trimmed = raw.trim();
    56	  if (trimmed === "") return "";
    57	  if (/^[a-z]+:\/\//i.test(trimmed)) return trimmed;
    58	  return `http://${trimmed}`;
    59	}
    60	
    61	/**
    62	 * Lower-cased hostname of a URL (no scheme, port, path, credentials), or "" if
    63	 * unparseable. Deliberately string-based rather than `new URL()`: it has to
    64	 * cope with the half-typed values a settings field holds.
    65	 */
    66	export function hostOf(url: string): string {
    67	  const stripped = url.trim().replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
    68	  const end = stripped.search(/[/?#]/);
    69	  const authority = end === -1 ? stripped : stripped.slice(0, end);
    70	  const host = authority.replace(/^[^@]*@/, "").replace(/:\d+$/, "");
