262	// --- Add ---
263	// savePath/label are interpolated into rtorrent COMMAND strings
264	// (d.directory.set="…" / d.custom1.set=…) that rtorrent's own parser evaluates
265	// AFTER XML decoding — a layer escapeXml (XML-only) does not protect. rtorrent
266	// offers no escape there, so strip the characters that would break out of the
267	// argument: a double-quote closes the quoted literal early and a control char
268	// (newline, CR, NUL, …) ends/splits the command. Paths/labels containing these
269	// are exceedingly rare; stripping is safer than silently corrupting the add.
270	export function sanitizeCommandArg(s: string): string {
271	  // Path/label chars (spaces, hyphens, slashes, …) are preserved; only the
272	  // double-quote and ASCII control chars are dropped.
273	  let out = "";
274	  for (const ch of s) {
275	    if (ch === '"' || ch.charCodeAt(0) < 0x20) continue;
276	    out += ch;
277	  }
278	  return out;
279	}
