251	    // erase. Files are only removed if ruTorrent's erasedata plugin is wired
252	    // into rtorrent's event hooks — without it this is an erase-only.
253	    return [
254	      { method: "d.custom5.set", params: [str(h), str("1")] },
255	      { method: "d.delete_tied", params: [str(h)] },
256	      { method: "d.erase", params: [str(h)] },
257	    ];
258	  });
259	  if (calls.length) await rpcMulticall(calls, instanceId);
260	}
