     1	import { getDb } from "../client.js";
     2	
     3	/**
     4	 * One passphrase-encrypted config backup per paired device, plus the web
     5	 * editor's reserved slot (Refs #385).
     6	 *
     7	 * The envelope is opaque: the backend stores and hands back exactly what was
     8	 * uploaded and never holds the passphrase. Slots deliberately outlive the
     9	 * device row (no FK, no cascade): the app's "Rotate secret" and "Unpair" both
    10	 * delete the device, and a reinstall re-pairs under the same id, so a slot
    11	 * must survive all three for the restore flow to have anything to offer.
    12	 * `platform` is copied at upload time so an orphaned slot still displays.
    13	 *
    14	 * `revision` comes from one counter shared by every slot (kv row
    15	 * `config_backup:revision_seq`), so it is globally monotonic: a slot that is
    16	 * deleted and recreated gets a revision higher than anything seen before,
    17	 * which is what lets a stale editor tab be refused and a phone notice the
    18	 * recreated web slot. The web editor sends the revision it loaded and
    19	 * `upsertBackupIfRevision` refuses the write when it no longer matches, inside
    20	 * one transaction (better-sqlite3 is synchronous, so the check and the write
    21	 * cannot interleave).
    22	 */
    23	
    24	interface ConfigBackupMetaRow {
    25	  device_id: string;
    26	  size_bytes: number;
    27	  config_version: number;
    28	  exported_at: number;
    29	  platform: string;
    30	  app_version: string | null;
    31	  updated_at: number;
    32	  revision: number;
    33	  paired: number;
    34	  last_seen_at: number | null;
    35	}
    36	
    37	export interface ConfigBackupMeta {
    38	  deviceId: string;
    39	  sizeBytes: number;
    40	  configVersion: number;
    41	  exportedAt: number;
    42	  platform: string;
    43	  appVersion: string | null;
    44	  updatedAt: number;
    45	  revision: number;
    46	  /** The device row still exists (false after unpair / rotate, always false for the web slot). */
    47	  paired: boolean;
