   188	export function deleteBackup(deviceId: string, expectedRevision?: number): boolean {
   189	  if (expectedRevision === undefined) {
   190	    return getDb().prepare("DELETE FROM config_backup WHERE device_id = ?").run(deviceId).changes > 0;
   191	  }
   192	  return (
   193	    getDb()
   194	      .prepare("DELETE FROM config_backup WHERE device_id = ? AND revision = ?")
   195	      .run(deviceId, expectedRevision).changes > 0
   196	  );
   197	}

