    11	
    12	/**
    13	 * Per-device config backup slots (Refs #385) — security model
    14	 * -----------------------------------------------------------
    15	 * The body is the app's passphrase-encrypted export envelope. The backend
    16	 * validates its shape and stores it verbatim; it never sees the passphrase
    17	 * and cannot decrypt it. That is what makes the read routes acceptable
    18	 * where GET /config is not (see routes/config.ts): a paired bearer can
    19	 * already rewrite the whole config, so handing it ciphertext it cannot open
    20	 * adds no privilege. Any paired device may read or delete any slot — that
    21	 * is the sharing flow (a second phone pairs, restores, and only the
    22	 * passphrase changes hands). What a stolen bearer gains is an offline
    23	 * guessing target for the passphrase, which the README documents.
    24	 *
    25	 * Slots are keyed by devices.id and outlive the device row on purpose (see
    26	 * db/repos/config-backup.ts). PUT always writes the caller's own slot. The
    27	 * reserved "web" slot (routes/ui-backups.ts) is readable and deletable here
    28	 * like any other, so a phone can apply or discard what was edited on the web.
    29	 *
    30	 * The 1 MB global bodyLimit is raised per route here: a large real config is
    31	 * a few hundred KB once hex-encoded, so 4 MB is generous and still bounded.
    32	 * PUT and DELETE get a tighter rate limit than the surrounding 120/min scope
    33	 * because each one is a full-row SQLite write.
    34	 */
    35	
    36	export const BODY_LIMIT = MAX_BACKUP_CIPHERTEXT_CHARS + 64 * 1024;
    37	export const WRITE_LIMIT = { max: 10, timeWindow: "1 minute" };
    38	
    39	const deviceIdParam = z.object({ deviceId: backupSlotIdSchema });
    40	
    41	export async function configBackupRoutes(app: FastifyInstance): Promise<void> {
    42	  app.put(
    43	    "/config/backup",
    44	    { preHandler: requireBearer, bodyLimit: BODY_LIMIT, config: { rateLimit: WRITE_LIMIT } },
    45	    async (request, reply) => {
    46	      const device = request.device;
    47	      if (!device) return reply.code(401).send({ error: "unauthenticated" });
    48	      const parsed = configBackupPutSchema.safeParse(request.body);
    49	      if (!parsed.success) {
    50	        return reply.code(400).send({ error: "invalid_payload" });
    51	      }
    52	      const { envelope, configVersion, exportedAt, appVersion } = parsed.data;
    53	      const result = upsertBackup({
    54	        deviceId: device.id,
    55	        envelope: JSON.stringify(envelope),
    56	        configVersion,
    57	        exportedAt,
    58	        platform: device.platform,
    59	        appVersion: appVersion ?? device.appVersion,
    60	      });
    61	      request.log.info(
    62	        { deviceId: device.id, bytes: result.sizeBytes, configVersion },
    63	        "config backup stored",
    64	      );
    65	      return { ok: true, updatedAt: result.updatedAt, sizeBytes: result.sizeBytes, revision: result.revision };
    66	    },
    67	  );
    68	
    69	  app.get("/config/backups", { preHandler: requireBearer }, async (request, reply) => {
    70	    const device = request.device;
    71	    if (!device) return reply.code(401).send({ error: "unauthenticated" });
    72	    return {
    73	      backups: listBackupMeta().map((m) => ({ ...m, mine: m.deviceId === device.id })),
    74	    };
    75	  });
    76	
    77	  app.get<{ Params: { deviceId: string } }>(
    78	    "/config/backups/:deviceId",
    79	    { preHandler: requireBearer },
    80	    async (request, reply) => {
    81	      const device = request.device;
    82	      if (!device) return reply.code(401).send({ error: "unauthenticated" });
    83	      const params = deviceIdParam.safeParse(request.params);
    84	      if (!params.success) return reply.code(400).send({ error: "invalid_payload" });
    85	      const found = getBackup(params.data.deviceId);
    86	      if (!found) return reply.code(404).send({ error: "not_found" });
    87	      request.log.info(
    88	        { deviceId: device.id, slot: found.meta.deviceId, bytes: found.meta.sizeBytes },
    89	        "config backup downloaded",
    90	      );
    91	      return {
    92	        ...found.meta,
    93	        mine: found.meta.deviceId === device.id,
    94	        envelope: JSON.parse(found.envelope) as unknown,
    95	      };
    96	    },
    97	  );
    98	
    99	  app.delete<{ Params: { deviceId: string } }>(
   100	    "/config/backups/:deviceId",
   101	    { preHandler: requireBearer, config: { rateLimit: WRITE_LIMIT } },
   102	    async (request, reply) => {
   103	      const device = request.device;
   104	      if (!device) return reply.code(401).send({ error: "unauthenticated" });
   105	      const params = deviceIdParam.safeParse(request.params);
   106	      if (!params.success) return reply.code(400).send({ error: "invalid_payload" });
   107	      if (!deleteBackup(params.data.deviceId)) {
   108	        return reply.code(404).send({ error: "not_found" });
   109	      }
   110	      request.log.info({ deviceId: device.id, slot: params.data.deviceId }, "config backup deleted");
   111	      return { ok: true };
   112	    },
   113	  );
   114	}
