 1	import type { FastifyInstance } from "fastify";
 2	import { z } from "zod";
 3	import { requireSameOrigin } from "../auth/same-origin.js";
 4	import {
 5	  deleteBackup,
 6	  getBackup,
 7	  upsertBackupIfRevision,
 8	} from "../db/repos/config-backup.js";
 9	import { backupSlotIdSchema, uiBackupPutSchema } from "../types.js";
10	import { WEB_SLOT_ID } from "../ui/overview-types.js";
11	import { BODY_LIMIT, WRITE_LIMIT } from "./config-backup.js";
12	import { requireUiSession, type UiRouteOptions } from "./ui.js";
13	
14	/**
15	 * The web editor's backup routes (Refs #385), behind the UI session cookie.
16	 *
17	 * Reads hand back any slot's envelope: it is ciphertext the browser decrypts
18	 * with a passphrase the backend never sees, so this exposes nothing the
19	 * bearer routes do not. Writes go only to the reserved "web" slot, never to a
20	 * phone's, and carry the revision the editor loaded so a stale tab gets a 409
21	 * instead of clobbering a newer save. Writes also pass `requireSameOrigin`,
22	 * the CSRF gate the read-only model did not need.
23	 *
24	 * Logs record slot ids and sizes, never envelope contents.
25	 */
