    10	
    11	export type BearerOutcome = "anonymous" | "authenticated";
    12	
    13	/**
    14	 * Optional-auth resolver, for routes that answer anonymous callers with a
    15	 * reduced public projection instead of a flat 401. Currently only /health.
    16	 *
    17	 * Authenticates by looking up the presented Bearer against the
    18	 * `devices.shared_secret` column. The secret is 32 bytes of `crypto.randomBytes`
    19	 * (~256 bits of entropy) — well beyond any practical brute-force — so plain
    20	 * SQL equality is sufficient. We do not wrap the comparison in `timingSafeEqual`
    21	 * because the SQLite lookup already terminates the moment a match is found or
    22	 * not found; adding a node-level constant-time compare after the fact is dead
    23	 * code, not a defence.
    24	 *
    25	 * "anonymous" means the caller never tried to authenticate: no Authorization
    26	 * header, or one using a different scheme. That second case is not hypothetical
    27	 * — a forward-auth proxy (Authentik, Authelia) can inject its own `Basic …` on
    28	 * the proxied request, and treating that as a failed bearer would 401 an
    29	 * ordinary healthcheck and reproduce the confusion in issue #357.
    30	 *
    31	 * A `Bearer` that is empty or unknown still gets the 401: that caller MEANT to
    32	 * authenticate and got it wrong. The app always sends a bearer, and the 401 from
    33	 * `useBackendHealth` is the only way a rotated or wiped secret ever surfaces —
    34	 * answering it 200 would leave the app reporting "Connected" forever with its
    35	 * local notification fallback suppressed.
    36	 *
    37	 * Returns null once it has sent the 401; the caller must then return without
    38	 * touching the reply.
    39	 */
    40	export async function resolveBearer(
    41	  request: FastifyRequest,
    42	  reply: FastifyReply,
    43	): Promise<BearerOutcome | null> {
    44	  const header = request.headers.authorization;
    45	  // RFC 7235: the auth scheme is case-insensitive.
    46	  if (!header || !/^bearer\s/i.test(header)) return "anonymous";
    47	
    48	  const presented = header.slice(header.indexOf(" ") + 1).trim();
    49	  if (!presented) {
    50	    await reply.code(401).send({ error: "missing_bearer" });
    51	    return null;
    52	  }
    53	
    54	  const device = findDeviceBySecret(presented);
    55	  if (!device || device.invalid) {
    56	    await reply.code(401).send({ error: "invalid_bearer" });
    57	    return null;
    58	  }
    59	
    60	  touchDevice(device.id);
    61	  request.device = device;
    62	  return "authenticated";
    63	}
    64	
    65	/**
    66	 * Bearer-or-nothing guard for every route that has no public projection.
    67	 */
    68	export async function requireBearer(
    69	  request: FastifyRequest,
    70	  reply: FastifyReply,
    71	): Promise<void> {
    72	  const outcome = await resolveBearer(request, reply);
    73	  if (outcome === null) return; // 401 already sent
    74	  if (outcome === "anonymous") {
    75	    await reply.code(401).send({ error: "missing_bearer" });
    76	  }
    77	}
