     1	import type { FastifyInstance } from "fastify";
     2	import { claimPairingToken } from "../auth/pairing-tokens.js";
     3	import { pairClaimSchema } from "../types.js";
     4	import { createDevice } from "../db/repos/devices.js";
     5	
     6	/**
     7	 * Pairing flow — security model
     8	 * -----------------------------
     9	 * The pairing token and webhook secret are ONLY surfaced via the server
    10	 * console at startup (see `printStartupPairing` in index.ts). We deliberately
    11	 * do NOT expose any HTTP endpoint that mints a token, because the backend is
    12	 * expected to run on a LAN with HTTP and anyone who could hit such an endpoint
    13	 * would become a full-privilege paired device (with access to every service's
    14	 * API key and to webhook-forging). Access to the container console is a
    15	 * reasonable proxy for "owner of this deployment".
    16	 *
    17	 * Consequence: if the startup token expires before the user scans it,
    18	 * regeneration requires a container restart. That's intentional.
    19	 *
    20	 * Only /pair/claim is exposed, and it's rate-limited by the scope in index.ts.
    21	 */
    22	
    23	export async function pairRoutes(app: FastifyInstance): Promise<void> {
    24	  app.post("/pair/claim", async (request, reply) => {
    25	    const parsed = pairClaimSchema.safeParse(request.body);
    26	    if (!parsed.success) {
    27	      return reply.code(400).send({ error: "invalid_payload", issues: parsed.error.issues });
    28	    }
    29	
    30	    const ok = claimPairingToken(parsed.data.token);
    31	    if (!ok) {
    32	      return reply.code(401).send({ error: "invalid_or_expired_token" });
    33	    }
    34	
    35	    const device = createDevice({
    36	      expoPushToken: parsed.data.expoPushToken,
    37	      platform: parsed.data.platform,
    38	      appVersion: parsed.data.appVersion,
    39	    });
    40	
    41	    return {
    42	      deviceId: device.id,
    43	      sharedSecret: device.sharedSecret,
    44	    };
    45	  });
    46	}

