     1	import * as LocalAuthentication from "expo-local-authentication";
     2	
     3	/**
     4	 * Device auth gate shared by config export and backend backup enablement.
     5	 *
     6	 * A bystander with a momentarily-unlocked phone must not be able to dump
     7	 * every API key by exporting (or by turning on a continuous encrypted export)
     8	 * with a passphrase they chose. Skipped only when the device has no lock at
     9	 * all — there is no security boundary to enforce then.
    10	 *
    11	 * Resolves "cancelled" when the user backs out; throws on a hard failure so
    12	 * the caller surfaces it as an error rather than silently continuing.
    13	 */
    14	export async function requireDeviceAuth(promptMessage: string): Promise<"ok" | "cancelled"> {
    15	  const level = await LocalAuthentication.getEnrolledLevelAsync();
    16	  if (level === LocalAuthentication.SecurityLevel.NONE) return "ok";
    17	  const auth = await LocalAuthentication.authenticateAsync({
    18	    promptMessage,
    19	    fallbackLabel: "Use passcode",
    20	  });
    21	  if (auth.success) return "ok";
    22	  if (
    23	    "error" in auth &&
    24	    (auth.error === "user_cancel" || auth.error === "app_cancel" || auth.error === "system_cancel")
    25	  ) {
    26	    return "cancelled";
    27	  }
    28	  const reason = "error" in auth ? auth.error : "failed";
    29	  throw new Error(`Device authentication ${reason}`);
    30	}
