240	//
241	// Since Bazarr 1.5.6 these return 204 at once and run as background jobs; the
242	// caller refreshes through lib/job-watch.ts. Before 1.5.6 they block until the
243	// work is done, hence the long timeouts.
244	
245	/** Search one language automatically. */
246	export function searchSubtitle(
247	  target: SubtitleTarget,
248	  lang: LanguageChoice,
249	  instanceId?: string,
250	): Promise<void> {
251	  return serviceRequest<void>("bazarr", subtitlesRoute(target), {
252	    method: "PATCH",
253	    params: searchParams(target, lang),
254	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
255	    instanceId,
256	  });
257	}
258	
259	// Before 1.5.6 every search request stays open for the whole provider
260	// search, and Android's HTTP client runs only 5 at once per host; the rest
261	// would wait in its queue while their timeout already runs. A season's gaps
262	// go out a few at a time instead.
263	const SEARCH_CONCURRENCY = 4;
264	
265	/**
266	 * Several one-language searches at once (an episode's missing languages, a
267	 * season's gaps). Sent in parallel, up to SEARCH_CONCURRENCY at a time, so
268	 * one slow search can't hold back the rest; fails only when every search
269	 * failed, since the others did start.
270	 */
271	export async function searchSubtitles(
272	  requests: readonly { target: SubtitleTarget; lang: LanguageChoice }[],
273	  instanceId?: string,
274	): Promise<void> {
275	  const failures: unknown[] = [];
276	  let next = 0;
277	  const worker = async () => {
278	    while (next < requests.length) {
279	      const r = requests[next++];
280	      try {
281	        await searchSubtitle(r.target, r.lang, instanceId);
282	      } catch (err) {
283	        failures.push(err);
284	      }
285	    }
286	  };
287	  await Promise.all(
288	    Array.from({ length: Math.min(SEARCH_CONCURRENCY, requests.length) }, worker),
289	  );
290	  if (failures.length > 0 && failures.length === requests.length) {
291	    throw failures[0];
292	  }
293	}
294	
295	/** Search every missing language of one movie or one series. */
296	export function searchMissingSubtitles(
297	  target: { type: "movie"; radarrId: number } | { type: "series"; seriesId: number },
298	  instanceId?: string,
299	): Promise<void> {
300	  return target.type === "movie"
301	    ? searchWantedMovie(target.radarrId, instanceId)
302	    : serviceRequest<void>("bazarr", "/series", {
303	        method: "PATCH",
304	        body: JSON.stringify({ seriesid: target.seriesId, action: "search-missing" }),
305	        timeout: INTERACTIVE_SEARCH_TIMEOUT,
306	        instanceId,
307	      });
308	}
309	
310	export interface PickedSubtitleFile {
311	  uri: string;
312	  name: string;
313	  mimeType?: string | null;
314	}
315	
316	/** Upload a subtitle file for one language. */
317	export function uploadSubtitle(
318	  target: SubtitleTarget,
319	  file: PickedSubtitleFile,
320	  lang: LanguageChoice,
321	  instanceId?: string,
322	): Promise<void> {
323	  // serviceRequest keeps fetch's own multipart Content-Type for FormData.
324	  const form = new FormData();
325	  for (const [key, value] of Object.entries(uploadFields(target, lang))) {
326	    form.append(key, String(value));
327	  }
328	  form.append("file", {
329	    uri: file.uri,
330	    name: file.name,
331	    type: file.mimeType || "application/octet-stream",
332	  } as unknown as Blob);
333	  return serviceRequest<void>("bazarr", subtitlesRoute(target), {
334	    method: "POST",
335	    body: form,
336	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
337	    instanceId,
338	  });
339	}
340	
341	/** Delete an external subtitle file. */
342	export function deleteSubtitle(
343	  target: SubtitleTarget,
344	  sub: BazarrSubtitle,
345	  instanceId?: string,
346	): Promise<void> {
347	  return serviceRequest<void>("bazarr", subtitlesRoute(target), {
348	    method: "DELETE",
349	    params: deleteParams(target, sub),
350	    instanceId,
351	  });
352	}
353	
354	/**
355	 * Manual search: every enabled provider's candidates for every language in
356	 * the item's profile (there is no language filter). Slow and synchronous, so
357	 * it takes the query's abort signal and a long timeout.
358	 */
359	export async function manualSearchSubtitles(
360	  target: SubtitleTarget,
361	  instanceId?: string,
362	  signal?: AbortSignal,
363	): Promise<BazarrSubtitleResult[]> {
364	  const res = await serviceRequest<BazarrListResponse<BazarrSubtitleResult>>(
365	    "bazarr",
366	    providersRoute(target),
367	    {
368	      params: targetParams(target),
369	      timeout: BAZARR_MANUAL_SEARCH_TIMEOUT,
370	      signal,
371	      instanceId,
372	    },
373	  );
374	  return res.data ?? [];
375	}
