377	/**
378	 * Download one manual-search result. The fields go in the body: `subtitle` is
379	 * Bazarr's serialized result, often several KB, which a reverse proxy's URL
380	 * limit would reject as a query string. Bazarr reads JSON bodies as well.
381	 */
382	export function downloadSubtitleResult(
383	  target: SubtitleTarget,
384	  result: ProviderResultRef,
385	  instanceId?: string,
386	): Promise<void> {
387	  return serviceRequest<void>("bazarr", providersRoute(target), {
388	    method: "POST",
389	    body: JSON.stringify(downloadResultParams(target, result)),
390	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
391	    instanceId,
392	  });
393	}
