395	/** Sync, translate, extract or clean up one subtitle. */
396	export function runSubtitleTool(
397	  target: SubtitleTarget,
398	  sub: BazarrSubtitle,
399	  action: SubtitleToolAction,
400	  instanceId?: string,
401	): Promise<void> {
402	  return serviceRequest<void>("bazarr", "/subtitles", {
403	    method: "PATCH",
404	    params: toolParams(target, sub, action),
405	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
406	    instanceId,
407	  });
408	}
