410	/**
411	 * Change the language profile of a movie or series; null removes it. Bazarr
412	 * only reads "" (or null/undefined) as "none" — "none" itself 404s.
413	 */
414	export function setLanguageProfile(
415	  target: { type: "movie"; radarrId: number } | { type: "series"; seriesId: number },
416	  profileId: number | null,
417	  instanceId?: string,
418	): Promise<void> {
419	  const idParam: Record<string, number> =
420	    target.type === "movie" ? { radarrid: target.radarrId } : { seriesid: target.seriesId };
421	  return serviceRequest<void>("bazarr", target.type === "movie" ? "/movies" : "/series", {
422	    method: "POST",
423	    params: { ...idParam, profileid: profileId === null ? "" : profileId },
424	    instanceId,
425	  });
426	}
427	
428	/** Search every wanted subtitle of every movie, or of every series. */
429	export function searchAllWanted(kind: "movies" | "series", instanceId?: string): Promise<void> {
430	  return serviceRequest<void>("bazarr", kind === "movies" ? "/movies" : "/series", {
431	    method: "PATCH",
432	    body: JSON.stringify({ action: "search-wanted" }),
433	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
434	    instanceId,
435	  });
436	}
437	
438	/**
439	 * Blacklist a downloaded subtitle from history: Bazarr deletes the file,
440	 * blacklists that provider result and searches the language again — all in
441	 * this one call.
442	 */
443	export function blacklistSubtitle(
444	  target: SubtitleTarget,
445	  entry: { provider: string; subs_id: string; language: string; subtitles_path: string },
446	  instanceId?: string,
447	): Promise<void> {
448	  return serviceRequest<void>("bazarr", blacklistRoute(target), {
449	    method: "POST",
450	    params: { ...targetParams(target), ...entry },
451	    timeout: INTERACTIVE_SEARCH_TIMEOUT,
452	    instanceId,
453	  });
454	}
455	
456	// --- Radarr/Sonarr link detection ---
457	
458	export interface ArrLinkSideResult {
459	  // The matched app instance, or null.
460	  instanceId: string | null;

