const cases = [
  { label: "port typed as 70000", form: { name: "<private>", mac: "AA:BB:CC:DD:EE:FF", broadcastAddress: "", port: "70000" } },
  { label: "port typed as 9.5", form: { name: "<private>", mac: "AA:BB:CC:DD:EE:FF", broadcastAddress: "", port: "9.5" } },
