567	// alone and letting useNetworkAutoSwitch re-evaluate later leaves a window
568	// where the flag still says "home" for a network that no longer exists in the
569	// list — and the invalidation that follows would refetch through the local
570	// URL inside that window (#418 review).
571	//
572	// The re-check only ever TIGHTENS (home → away). It never loosens away → home
573	// from the stored identity: `currentWifi` stops being refreshed while no home
574	// network is configured (useNetworkAutoSwitch bails), so by the time the user
575	// adds a network again the device may be on a different LAN with the old
576	// identity still cached. Clearing home is the evaluator's job — the edit
577	// re-runs it (the hook depends on homeNetworks) and it reads NetInfo fresh.
578	// For the same reason the identity is dropped when the list becomes empty.
579	function homeNetworksPatch(
580	  state: Pick<
581	    ConfigState,
582	    | "autoSwitchNetwork"
583	    | "demoMode"
584	    | "treatVpnAsHome"
585	    | "isVpnActive"
586	    | "currentWifi"
587	    | "networkAwayFromHome"
588	    | "dashboards"
589	    | "activeDashboardId"
590	  >,
591	  next: HomeNetwork[],
592	): Pick<ConfigState, "homeNetworks"> &
593	  Partial<Pick<ConfigState, "networkAwayFromHome" | "currentWifi">> {
594	  setJSON(STORAGE_KEYS.homeNetworks, next);
595	  const identity = next.length === 0 ? { currentWifi: null } : {};
596	  // Auto-switch off / demo: getActiveUrl ignores the flag and the evaluator
597	  // no-ops, so leave it untouched exactly as the evaluator would.
598	  if (!state.autoSwitchNetwork || state.demoMode) {
599	    return { homeNetworks: next, ...identity };
600	  }
601	  if (state.networkAwayFromHome) return { homeNetworks: next, ...identity };
602	  // Currently home: stay home only if the VPN opt-in still vouches for it
603	  // (#185, live via the liveness poll) or the network we matched is still in
604	  // the active dashboard's effective selection of the NEW list.
605	  if (state.treatVpnAsHome && state.isVpnActive) {
606	    return { homeNetworks: next, ...identity };
607	  }
608	  const active =
609	    state.dashboards.find((d) => d.id === state.activeDashboardId) ??
610	    state.dashboards[0];
611	  return {
612	    homeNetworks: next,
613	    ...identity,
614	    networkAwayFromHome: !matchesHomeNetwork(
615	      state.currentWifi,
616	      effectiveHomeNetworksOf(active, next),
617	    ),
618	  };
619	}
